const O={};globalThis.P=(en,ar)=>({en,ar});try{globalThis["D"]=O["D"]=({"sites":[{"id":"bat-al-khutm-al-ayn","n":"Bat, Al-Khutm and Al-Ayn","na":"بات والخطم والعين","c":"archaeological","s":"Bronze Age towers and tombs · World Heritage","lat":23.2699,"lng":56.745,"p":"Hafit and Umm an-Nar periods","dr":"3rd millennium BC","el":"Towers about 20 m across","ic":"mound","era":"P","t0":5025,"t1":4025,"te":"Towers with no doors","ta":"أبراج بلا أبواب","se":"Round stone buildings 20 m wide whose purpose is still unknown, and a hillside of beehive tombs","sa":"مبانٍ حجرية دائرية بعرض 20 م لا يُعرف غرضها، وسفح من قبور كخلايا النحل","desc":"A 3rd-millennium BC necropolis and settlement in Al Dhahirah: at Bat about 100 graves and circular buildings each about 20 m in diameter with no outside openings; at Al-Khutm, 2 km west, a rock tower of 20 m thought to be a fort; and at Al-Ayn, 22 km south-east, the best-preserved line of beehive tombs on a ridge. A Danish team under Karen Frifelt excavated in 1972 and found some 4,000 years of continuous occupation. Inscribed in 1988 under criteria (iii) and (iv), Oman's second World Heritage site.","sig":"The most complete Bronze Age settlement and cemetery landscape of the 3rd millennium BC in the world, per UNESCO.","ex":"Danish expedition (K. Frifelt) 1972; University of Pennsylvania Bat Archaeological Project 2007–2012","disc":["Circular towers 20 m across without doors","Beehive tombs of Al-Ayn"],"refs":["Thornton, C. P., Cable, C. M. & Possehl, G. L. (2016). The Bronze Age Towers at Bat, Sultanate of Oman. University of Pennsylvania Press.","UNESCO World Heritage Centre. Archaeological Sites of Bat, Al-Khutm and Al-Ayn (ref. 434), inscribed 1988."],"conf":"","ev":"","an":"","val":""},{"id":"bahla-fort","n":"Bahla Fort","na":"قلعة بهلاء","c":"archaeological","s":"Mud-brick fortress of the Banu Nabhan · World Heritage","lat":22.9642,"lng":57.3011,"p":"Islamic (Nabhani to Ya’ariba)","dr":"12th – 18th century AD","el":"Oasis wall about 13 km","ic":"wall","era":"H","t0":900,"t1":250,"te":"A castle made of earth","ta":"قلعة من تراب","se":"A mud-brick fortress and a 13 km wall around an oasis famous for its potters","sa":"قلعة من الطوب الطيني وسور بطول 13 كم حول واحة اشتهرت بخزّافيها","desc":"A fortress of mud brick and straw at the foot of the Jebel Akhdar, believed to have been built between the 12th and 15th centuries by the Banu Nabhan, with the Al-Qasabah as its oldest part, the Bait al-Hadith of the Ya'ariba dynasty (1624–1743) and the 18th-century Bait al-Jabal. A wall of about 13 km, partly standing, encloses the oasis. Inscribed in 1987 as Oman's first World Heritage site, placed on the List in Danger from 1988 to 2004 because of decay of the unfired brick, and reopened in 2012 after a long restoration.","sig":"The largest surviving earthen fortress of the Gulf and a lesson in how to conserve mud architecture.","ex":"Ministry of Heritage and Tourism; ArCHIAM Centre management plan 2013","disc":["Three building phases from the 12th to the 18th century","Oasis wall of about 13 km"],"refs":["UNESCO World Heritage Centre. Bahla Fort (ref. 433), inscribed 1987; State of Conservation report 2018.","ArCHIAM Centre (2013). Bahla Fort and Oasis heritage management plan."],"conf":"","ev":"","an":"","val":""},{"id":"khor-rori-sumhuram","n":"Khor Rori (Sumhuram)","na":"خور روري (سمهرم)","c":"archaeological","s":"Frankincense port · World Heritage","lat":17.038,"lng":54.433,"p":"Late pre-Islamic","dr":"Late 1st century BC – 5th century AD","el":"Walled town above a lagoon","ic":"boat","era":"H","t0":2050,"t1":1550,"te":"The port of incense","ta":"ميناء البخور","se":"A walled port founded by the kings of Hadramawt to ship frankincense to Rome and India","sa":"ميناء مسوّر أسسه ملوك حضرموت لشحن اللبان إلى روما والهند","desc":"A fortified port on a lagoon east of Salalah, founded at the end of the 1st century BC by the kingdom of Hadramawt to control the Dhofar incense trade, and identified with the Moscha of classical texts. Inscriptions in the gate name the city Sumhuram; warehouses, a temple and houses lie within the walls. One of four components of the Land of Frankincense property (849.88 ha) inscribed in 2000 under criteria (iii) and (iv) and renamed in 2005.","sig":"The best-preserved pre-Islamic port of the incense route, where South Arabian script meets Roman and Indian trade.","ex":"American Foundation for the Study of Man 1952–53; Italian Mission to Oman (University of Pisa) 1997 onwards","disc":["Gate inscriptions naming Sumhuram","Warehouses for frankincense"],"refs":["UNESCO World Heritage Centre. Land of Frankincense (ref. 1010), inscribed 2000.","Avanzini, A. (ed.) (2008). A Port in Arabia between Rome and the Indian Ocean (3rd C. BC – 5th C. AD): Khor Rori Report 2. L'Erma di Bretschneider."],"conf":"","ev":"","an":"","val":""},{"id":"al-baleed","n":"Al-Baleed (Zafar)","na":"البليد (ظفار)","c":"archaeological","s":"Medieval port of Dhofar · World Heritage","lat":17.0,"lng":54.12,"p":"Islamic","dr":"c. 10th – 16th century AD","el":"Port with citadel and grand mosque","ic":"platform","era":"H","t0":1050,"t1":450,"te":"The city Marco Polo saw","ta":"المدينة التي رآها ماركو بولو","se":"A walled medieval port that sold frankincense and horses to China and India","sa":"ميناء مسوّر من العصور الوسطى باع اللبان والخيول للصين والهند","desc":"The ruins of the medieval city of Zafar on the Salalah shore: a walled port with a citadel and a grand mosque, visited by Ibn Battuta and recorded by Marco Polo's generation, which exported frankincense and Arabian horses across the Indian Ocean until its decline in the 16th century. It is a component of the Land of Frankincense World Heritage property and houses the Museum of the Frankincense Land.","sig":"The medieval successor of Sumhuram and the last great port of the incense trade.","ex":"Office of the Adviser to His Majesty for Cultural Affairs; German (DAI) and American missions","disc":["Citadel and grand mosque","Horse-export port of the Middle Ages"],"refs":["UNESCO World Heritage Centre. Land of Frankincense (ref. 1010).","World Heritage Site community reviews, Land of Frankincense (worldheritagesite.org)."],"conf":"","ev":"","an":"","val":""},{"id":"shisr-ubar","n":"Shisr (Wubar)","na":"شصر (وبار)","c":"archaeological","s":"Caravan oasis of the incense road","lat":18.26,"lng":53.65,"p":"Pre-Islamic to Islamic","dr":"By 300 BC – 16th century AD","el":"Spring and collapsed fort at the desert edge","ic":"caravan","era":"H","t0":2325,"t1":450,"te":"The city lost in the sands","ta":"المدينة الضائعة في الرمال","se":"A caravan fort over a spring, identified in the 1990s with the legendary Ubar","sa":"حصن قوافل فوق عين، رُبط في التسعينيات بمدينة أوبار الأسطورية","desc":"A spring and fortified caravan station on the edge of the Rub' al Khali north of Thumrait, part of the incense trade network by 300 BC. Identified in the early 1990s by Sir Ranulph Fiennes and a team of archaeologists as the legendary Ubar, an identification still debated; part of the fort collapsed into the sinkhole of its own spring. A component of the Land of Frankincense World Heritage property.","sig":"The desert end of the incense road, where caravans watered before crossing to the Gulf.","ex":"Trans-Arabia Expedition (N. Clapp, R. Fiennes, J. Zarins) 1990–1995","disc":["Fort collapsed into its spring sinkhole","Trade goods from 300 BC onward"],"refs":["UNESCO World Heritage Centre. Land of Frankincense (ref. 1010).","Zarins, J. (2001). The Land of Incense: archaeological work in the Governorate of Dhofar. Sultan Qaboos University."],"conf":"","ev":"","an":"","val":""},{"id":"falaj-daris","n":"Falaj Daris and the Aflaj of Oman","na":"فلج دارس وأفلاج عُمان","c":"archaeological","s":"Living irrigation channels · World Heritage","lat":22.9833,"lng":57.5333,"p":"Iron Age to present","dr":"From c. AD 500 (tradition 5,000 years old)","el":"Five inscribed aflaj; c. 3,000 still flowing","ic":"river","era":"H","t0":1500,"t1":0,"te":"Water shared by the minute","ta":"ماء يُقسَّم بالدقيقة","se":"Underground channels up to 12 km long bring mountain water to oases, still divided by the stars","sa":"قنوات تحت الأرض بطول 12 كم تجلب ماء الجبل إلى الواحات، وما زالت تُقسَّم بالنجوم","desc":"Falaj Daris at Nizwa is the largest of five aflaj inscribed in 2006 (with Al-Khatmeen, Al-Malki, Al-Mayassar and Al-Jeela) under criterion (v). About 3,000 aflaj still function in Oman; the systems date from around AD 500 within a 5,000-year irrigation tradition. Daudi aflaj (23.5%) run underground up to 12 km and 50 m deep; ghaili aflaj (48.5%) are seasonal open channels; aini aflaj (28%) carry spring water, sometimes hot. Water is shared by timed turns under a management system that has survived for centuries.","sig":"The most extensive living example of ancient water engineering in Arabia.","ex":"Ministry of Agriculture, Fisheries and Water Resources (Aflaj inventory)","disc":["Daudi channels up to 12 km long","About 3,000 working aflaj"],"refs":["UNESCO World Heritage Centre. Aflaj Irrigation Systems of Oman (ref. 1207), inscribed 2006.","Al-Ghafri, A. S. (2018). Overview about the aflaj of Oman. Proceedings of the International Symposium of Khettaras and Qanats."],"conf":"","ev":"","an":"","val":""},{"id":"qalhat","n":"Ancient City of Qalhat","na":"مدينة قلهات القديمة","c":"archaeological","s":"Hormuz-era port · World Heritage","lat":22.6994,"lng":59.3694,"p":"Islamic","dr":"11th – 16th century AD","el":"About 24 ha within walls","ic":"jar","era":"H","t0":950,"t1":450,"te":"The queen’s mosque","ta":"مسجد الملكة","se":"A port that Marco Polo and Ibn Battuta praised, ruled by a woman after 1311","sa":"ميناء أثنى عليه ماركو بولو وابن بطوطة، حكمته امرأة بعد عام 1311","desc":"The ruins of a walled port of more than 24 ha north of Sur, the second city of the Kingdom of Hormuz. Marco Polo called it Calatu in the 13th century and Ibn Battuta in the 14th praised its bazaars and a mosque built by Bibi Maryam, who ruled Qalhat and Hormuz after her husband Ayaz died in 1311–12; her mausoleum, now without its dome, is the main standing monument. The city declined as trade moved to Muscat, was taken by the Portuguese by 1507, and earthquakes on the Qalhat Fault are a plausible cause of its ruin. Inscribed in 2018.","sig":"A rare intact medieval Indian Ocean port, abandoned early and never rebuilt.","ex":"French Archaeological Mission at Qalhat (A. Rougeulle), 2008 onwards","disc":["Mausoleum of Bibi Maryam","City walls and water cisterns"],"refs":["UNESCO World Heritage Centre. Ancient City of Qalhat (ref. 1537), inscribed 2018.","Rougeulle, A. (ed.) (2017). Qalhāt, Oman: a medieval port city. Archaeopress."],"conf":"","ev":"","an":"","val":""},{"id":"ras-al-jinz-rj2","n":"Ras al-Jinz Bronze Age Village (RJ-2)","na":"قرية رأس الجنز من العصر البرونزي","c":"archaeological","s":"Fishing village in contact with the Indus","lat":22.41,"lng":59.83,"p":"Bronze Age","dr":"c. 2300 – 2000 BC","el":"1 km² of remains · 100 sites · 350 graves","ic":"boat","era":"P","t0":4325,"t1":4025,"te":"Fishermen who knew the Indus","ta":"صيادون عرفوا السند","se":"A village at the easternmost point of Arabia that traded with India 4,000 years ago","sa":"قرية في أقصى شرق الجزيرة العربية تاجرت مع الهند قبل 4,000 عام","desc":"Remains covering about 1 km² at the easternmost point of Arabia, 11 km south of Ras al Hadd, with 100 documented sites and some 350 graves on the mesa above Khawr Jarama. Occupation runs from the early Holocene to the Iron Age; steatite vessels date to about 2300 BC, an incense burner to 2200 BC and settlements to 2000 BC. A potsherd with a Harappan inscription found in 1982 shows contact with the Indus Valley, with bitumen, stamp seals, fish hooks, metal pins and an Indian ivory comb among the finds. On the UNESCO Tentative List with the turtle reserve (2013).","sig":"Evidence that Oman's fishermen were part of the Bronze Age world linking Mesopotamia, the Gulf and the Indus.","ex":"Joint Hadd Project (S. Cleuziou, M. Tosi), 1985–2000s","disc":["Harappan-inscribed potsherd (1982)","Indian ivory comb"],"refs":["UNESCO World Heritage Centre. Ras al Had Turtle Reserve and the Heritage Site of Ras al Jinz, Tentative List ref. 5840 (2013).","Cleuziou, S. & Tosi, M. (2007). In the Shadow of the Ancestors: the prehistoric foundations of the early Arabian civilization in Oman. Ministry of Heritage and Culture."],"conf":"","ev":"","an":"","val":""},{"id":"semail-ophiolite","n":"Semail Ophiolite","na":"أفيوليت سمائل","c":"geological","s":"The world’s largest slice of ocean crust on land","lat":23.39,"lng":57.83,"p":"Late Cretaceous","dr":"Crust formed 96 – 94 million years ago; thrust onto Arabia soon after","el":"550 km long · 150 km wide · over 10,000 km²","ic":"fault","era":"D","t0":96000000.0,"t1":70000000.0,"te":"The sea floor that climbed onto the land","ta":"قاع البحر الذي صعد إلى اليابسة","se":"Oman’s dark mountains are a 550 km sheet of oceanic crust and mantle pushed over the continent","sa":"جبال عُمان الداكنة صفيحة من قشرة المحيط ووشاحه بطول 550 كم دُفعت فوق القارة","desc":"The Hajar Mountains are built largely of the Semail ophiolite, described as the world's largest and best-preserved thrust sheet of oceanic crust and upper mantle: more than 10,000 km², about 550 km long and 150 km wide. The crust formed 96–94 million years ago at a spreading centre above a north-east-dipping subduction zone and was emplaced onto the Arabian margin in the Late Cretaceous; its metamorphic sole formed at about 850 °C 95–93 million years ago, and eclogites at As Sifah record continental crust dragged 78–90 km down. The sequence, from arc lavas and pillow basalts through gabbros to more than 12 km of mantle harzburgite, can be walked across in a day in wadis such as Wadi Al Abyad.","sig":"The reference ophiolite of the planet, where geologists go to see the ocean floor and the mantle at the surface.","ex":"Oxford (M. Searle) and international teams; Oman Drilling Project 2017–2018","disc":["Mantle rock exposed at the surface","Eclogites from 78–90 km depth at As Sifah"],"refs":["Searle, M. & Cox, J. Tectonic setting, origin, and obduction of the Oman ophiolite. Geological Society of America Bulletin 111(1), 104–122 (1999)."],"conf":"","ev":"","an":"","val":""},{"id":"jebel-shams","n":"Jebel Shams and Wadi Nakhr","na":"جبل شمس ووادي نخر","c":"geological","s":"Oman’s highest peak and its Grand Canyon","lat":23.237,"lng":57.264,"p":"Permian to Cretaceous","dr":"Limestone laid down 270 – 90 million years ago","el":"3,010 m · canyon 1,000 m deep","ic":"cliff","era":"D","t0":270000000.0,"t1":90000000.0,"te":"Three thousand metres of sea floor","ta":"ثلاثة آلاف متر من قاع البحر","se":"A canyon a kilometre deep cuts through the whole Hajar Supergroup","sa":"أخدود بعمق كيلومتر يشق مجموعة الحجر الكبرى بأكملها","desc":"At 3,010 m Jebel Shams is the highest point of the Jebel Akhdar and of Oman, in a range about 700 km long. Wadi Nakhr, the 'Grand Canyon of Arabia', is 12 km long, over 1 km wide at the viewpoint and more than 1,000 m deep, cutting through about 3,000 m of the Hajar Supergroup, shallow-marine limestone deposited from the Late Permian to the Late Cretaceous: Jurassic Sahtan oolitic limestone, Lower Cretaceous Kahmah limestone and marl, and the mid-Cretaceous Natih limestone over Nahr Umr shale, the same reservoir rocks that hold Oman's oil.","sig":"The clearest exposure of the rocks beneath Arabia's oil fields, visible from a single viewpoint.","ex":"Petroleum Development Oman geological surveys; GeoExpro (Whaley 2018)","disc":["Canyon over 1,000 m deep","Entire Hajar Supergroup exposed"],"refs":["Whaley, J. (2018). The Grand Canyon of the Middle East. GEO ExPro, 3 December 2018."],"conf":"","ev":"","an":"","val":""},{"id":"majlis-al-jinn","n":"Majlis al Jinn","na":"مجلس الجن","c":"geological","s":"One of the largest cave chambers on Earth","lat":22.88,"lng":59.09,"p":"Quaternary karst in Eocene rock","dr":"Chamber in Middle Eocene Dammam limestone","el":"310 × 225 m · 120 m high · 1,380 m a.s.l.","ic":"sinkhole","era":"D","t0":2580000.0,"t1":0,"te":"The meeting place of the spirits","ta":"مجلس الجن","se":"A chamber big enough to hold ten jumbo jets, entered only by rope through holes in its roof","sa":"قاعة تتسع لعشر طائرات جامبو، لا تُدخل إلا بالحبل عبر فتحات في سقفها","desc":"A single chamber about 310 m long, 225 m wide and 120 m high, with a floor of 58,000 m² and a volume of about 4 million m³, beneath the Selma Plateau at 1,380 m, 100 km south-east of Muscat. Formed in fossiliferous marly limestone of the Middle Eocene Dammam Formation under a roof only 40 m thick, it is entered by free descent through three ceiling holes (Cheryl's Drop 158 m, Asterisk 140 m, First Drop 118 m). Discovered in June 1983 by Don Davison and Cheryl Jones and surveyed in 1985, when it ranked second in the world by volume; it has been closed by the government since 2008.","sig":"A world-ranking cave chamber, and the same Dammam Formation that forms the aquifer of Bahrain and Qatar.","ex":"Public Authority for Water Resources (survey 1985)","disc":["Volume about 4,000,000 m³","Entrance drops up to 158 m"],"refs":["Public Authority for Water Resources, Oman (1985). Report PAWR 85-20.","Davison, W. D. (1990). Meeting place of the spirits. Aramco World, Sept–Oct 1990."],"conf":"","ev":"","an":"","val":""},{"id":"sharqiya-sands","n":"Sharqiya (Wahiba) Sands","na":"رمال الشرقية (الوهيبة)","c":"geological","s":"A sand sea 180 km long","lat":22.3,"lng":58.8,"p":"Quaternary","dr":"Dunes formed after the last ice age","el":"12,500 km² · dunes to 100 m","ic":"dune","era":"D","t0":11700,"t1":0,"te":"Dunes on a cemented floor","ta":"كثبان على أرضية متحجرة","se":"Living dunes 100 m high rest on an older desert turned to stone","sa":"كثبان حيّة بارتفاع 100 م تستقر فوق صحراء أقدم تحوّلت إلى حجر","desc":"A dune field of about 12,500 km², 180 km north–south and 80 km east–west, whose northern dunes rise to 100 m and rest on an older layer of cemented carbonate sand. The 1986 Royal Geographical Society expedition recorded 16,000 invertebrates, 200 other animal species and 150 native plants, including ghaf (Prosopis cineraria) woodland; Bedouin of the Al Wahiba and other tribes still gather at the Al-Huyawah oasis for the date harvest.","sig":"One of the best-studied sand seas in the world and the type example of a dune field in the monsoon belt.","ex":"Royal Geographical Society Oman Wahiba Sands Project, 1985–1987","disc":["Cemented sand beneath the living dunes","16,000 invertebrates recorded in 1986"],"refs":["Dutton, R. W. (ed.) (1988). The Scientific Results of the Royal Geographical Society's Oman Wahiba Sands Project 1985–1987. Journal of Oman Studies Special Report 3.","Pease, P. P. et al. (1999). Mineralogical characterization and transport pathways of dune sand using Landsat TM data, Wahiba Sand Sea. Geomorphology."],"conf":"","ev":"","an":"","val":""},{"id":"ras-al-had-turtles","n":"Ras al Hadd Turtle Reserve","na":"محمية السلاحف في رأس الحد","c":"ecology","s":"Green turtle rookery","lat":22.52,"lng":59.78,"p":"Living today","dr":"Reserve since 23 April 1996","el":"120 km² · 45 km of coast","ic":"wave","era":"N","t0":30,"t1":0,"te":"Twenty thousand turtles come home","ta":"عشرون ألف سلحفاة تعود","se":"Most of Oman’s green turtles nest on one 45 km stretch of beach","sa":"تعشّش معظم سلاحف عُمان الخضراء على شريط شاطئ واحد بطول 45 كم","desc":"A 120 km² reserve declared on 23 April 1996 covering about 45 km of coast from Khawr Jarama to Ras Ruwais, with two lagoons, mangrove and coral at Khawr Jarama, about 130 bird species and the white stork on migration. About 20,000 green turtles nest on more than 275 beaches along Oman's coast and most nest within this reserve; 14 rangers and a visitor centre at Ras al-Jinz manage night viewing. On the UNESCO Tentative List since 2013 together with the Bronze Age site.","sig":"One of the largest green turtle nesting grounds in the Indian Ocean.","ex":"Environment Authority, Oman; Ras al-Jinz Scientific and Visitor Centre","disc":["About 20,000 nesting green turtles","45 km protected coastline"],"refs":["UNESCO World Heritage Centre. Ras al Had Turtle Reserve and the Heritage Site of Ras al Jinz, Tentative List ref. 5840 (2013)."],"conf":"","ev":"","an":"","val":""},{"id":"masirah-loggerheads","n":"Masirah Island Loggerheads","na":"سلاحف مصيرة ضخمة الرأس","c":"ecology","s":"Globally important loggerhead rookery","lat":20.45,"lng":58.78,"p":"Living today","dr":"Monitored 1977 – 2019","el":"83 km of nesting beach","ic":"wave","era":"N","t0":49,"t1":0,"te":"A decline inside one lifetime","ta":"تراجع في عمر جيل واحد","se":"From 20,000–40,000 females a year to about 10,000, mostly lost to fishing nets","sa":"من 20 إلى 40 ألف أنثى في السنة إلى نحو 10 آلاف، فُقد معظمها في شباك الصيد","desc":"Masirah Island's 83 km of beaches hold one of the world's most important loggerhead turtle rookeries. Nesting females were estimated at 20,000–40,000 a year in 1977–1986 but at 10,223–11,500 in 2008–2016 (about 55,000 nests a year); track counts on the index beaches fell 79% between 1985–1996 and 2008–2016, within a single turtle generation of about 47 years, and density fell further by 2019. Bycatch is the most likely cause: community surveys in 2013 estimated 1,640–1,770 loggerheads a year caught in artisanal gillnets. Demersal trawling has been illegal in Oman since 2011.","sig":"A warning from the Indian Ocean's largest loggerhead population, measured over forty years.","ex":"Environment Authority, Oman with Five Oceans Environmental Services (Willson et al. 2020)","disc":["79% decline in nesting tracks","1,640–1,770 turtles a year in gillnets"],"refs":["Willson, A., Witherington, B., Baldwin, R., Tiwari, M., Al Sariri, T., Al Kiyumi, A. et al. (2020). Evaluating the long-term trend and management of a globally important loggerhead population nesting on Masirah Island, Sultanate of Oman. Frontiers in Marine Science 7, 666."],"conf":"","ev":"","an":"","val":""},{"id":"jabal-samhan","n":"Jabal Samhan Nature Reserve","na":"محمية جبل سمحان","c":"ecology","s":"Stronghold of the Arabian leopard","lat":17.516,"lng":54.94,"p":"Living today","dr":"Royal Decree 48/97","el":"About 4,500 km²","ic":"gazelle","era":"N","t0":29,"t1":0,"te":"The last leopards","ta":"آخر النمور","se":"A 4,500 km² escarpment above Dhofar where the Arabian leopard still breeds","sa":"جرف بمساحة 4,500 كم² فوق ظفار ما زال النمر العربي يتكاثر فيه","desc":"A reserve of about 4,500 km² on the Jabal Samhan escarpment of Dhofar, established by Royal Decree 48/97, where camera-trap surveys confirmed a persisting population of the critically endangered Arabian leopard and a mother with cub was recorded in 2022. It also holds Arabian wolf, striped hyena, Arabian gazelle, Nubian ibex, rock hyrax, honey badger and red fox, with frankincense, wild fig, wild olive and acacia on its slopes and the monsoon fog of the khareef on its seaward face.","sig":"The most important site on Earth for the Arabian leopard, with fewer than 200 left in the wild.","ex":"Office for Conservation of the Environment, Diwan of Royal Court (J. A. Spalton)","disc":["Arabian leopard breeding confirmed","Nubian ibex and striped hyena"],"refs":["Spalton, J. A., Al Hikmani, H. M., Willis, D. & Said, A. S. B. (2006). Critically endangered Arabian leopards Panthera pardus nimr persist in the Jabal Samhan Nature Reserve, Oman. Oryx 40(3), 287–294.","Oman Observer (17 August 2026). Jabal Samhan Nature Reserve protects rich biodiversity in Dhofar."],"conf":"","ev":"","an":"","val":""},{"id":"dimaniyat-islands","n":"Dimaniyat Islands Nature Reserve","na":"محمية جزر الديمانيات","c":"ecology","s":"Coral islands off Muscat","lat":23.85,"lng":58.1,"p":"Living today","dr":"Reserve since 3 April 1996","el":"Nine islands, 16–18 km offshore","ic":"crab","era":"N","t0":30,"t1":0,"te":"Nine islands of birds and turtles","ta":"تسع جزر من الطيور والسلاحف","se":"Hawksbills, tropicbirds and corals on an archipelago reached only by boat","sa":"سلاحف منقار الصقر وطيور الاستوائي ومرجان على أرخبيل لا يُبلغ إلا بالقارب","desc":"Nine islands 16–18 km off the Batinah coast, declared a nature reserve on 3 April 1996 and submitted to the UNESCO Tentative List in 2013 under natural criterion (x). Some 250–300 hawksbill turtles nest each year and green turtles feed in the shallows; thousands of seabirds nest in summer, including red-billed tropicbird, osprey, roseate, white-cheeked, bridled and sooty terns and common noddy, over a multitude of coral species; humpback whales and dolphins pass offshore. Four rangers guard the islands and landing is restricted in the nesting season.","sig":"Oman's main hawksbill rookery and the richest coral site near the capital.","ex":"Environment Authority, Oman; Environment Society of Oman","disc":["250–300 hawksbill nests a year","Seven seabird species breeding"],"refs":["UNESCO World Heritage Centre. Al Dimaniyat Islands Nature Reserve, Tentative List ref. 5839 (2013)."],"conf":"","ev":"","an":"","val":""},{"id":"oryx-sanctuary","n":"Al Wusta Wildlife Reserve (former Arabian Oryx Sanctuary)","na":"محمية الوسطى (محمية المها العربي سابقًا)","c":"ecology","s":"Where the oryx returned, and the listing was lost","lat":19.95,"lng":57.1,"p":"Living today","dr":"World Heritage 1994 – 2007","el":"Jiddat al-Harasis gravel plain","ic":"gazelle","era":"N","t0":44,"t1":0,"te":"A lesson written in oryx","ta":"درس مكتوب بالمها","se":"The first site ever removed from the World Heritage List, after the herd fell from 450 to 65","sa":"أول موقع يُحذف من قائمة التراث العالمي، بعد أن تراجع القطيع من 450 إلى 65","desc":"The gravel plain of Jiddat al-Harasis where Arabian oryx bred in captivity were returned to the wild from 1982, inscribed as a World Heritage site in 1994. Poaching and habitat degradation cut the free herd from about 450 in 1996 to 65 by 2007, with about four breeding pairs, and after Oman reduced the protected area by 90% to allow hydrocarbon prospecting the World Heritage Committee removed the site on 28 June 2007, the first deletion in the List's history. Oryx are now kept in fenced enclosures in what is today the Al Wusta Wildlife Reserve.","sig":"A global landmark in conservation history, both for the oryx's return and for its loss.","ex":"Office for Conservation of the Environment, Diwan of Royal Court","disc":["Oryx reintroduced from 1982","Delisted by UNESCO in 2007"],"refs":["UNESCO World Heritage Centre (2007). Oman's Arabian Oryx Sanctuary: first site ever to be deleted from UNESCO's World Heritage List. News, 28 June 2007.","Spalton, J. A., Lawrence, M. W. & Brend, S. A. (1999). Arabian oryx reintroduction in Oman: successes and setbacks. Oryx 33(2)."],"conf":"","ev":"","an":"","val":""},{"id":"wadi-dawkah","n":"Wadi Dawkah Frankincense Park","na":"منتزه وادي دوكة للبان","c":"ecology","s":"Frankincense trees · World Heritage","lat":17.33,"lng":54.07,"p":"Living today","dr":"Harvested for over 2,000 years","el":"Boswellia sacra woodland north of Salalah","ic":"plant","era":"N","t0":2300,"t1":0,"te":"The trees that perfumed the ancient world","ta":"الأشجار التي عطّرت العالم القديم","se":"Boswellia sacra still bleeds resin in a protected valley 45 minutes from Salalah","sa":"ما زالت شجرة اللبان تنزف صمغها في وادٍ محميّ على بعد 45 دقيقة من صلالة","desc":"A natural woodland of Boswellia sacra, the frankincense tree, in a dry valley about 45 minutes' drive north of Salalah, where resin is still tapped by cutting the bark as it was for the incense trade of Sumhuram and Zafar. The park is one of the four components of the Land of Frankincense World Heritage property inscribed in 2000.","sig":"The living source of the trade that built the ports of Dhofar.","ex":"Ministry of Heritage and Tourism; Office of the Adviser for Cultural Affairs","disc":["Resin tapped by cutting the bark","Component of a World Heritage property"],"refs":["UNESCO World Heritage Centre. Land of Frankincense (ref. 1010), inscribed 2000."],"conf":"","ev":"","an":"","val":""},{"id":"khareef-wadi-darbat","n":"Khareef and Wadi Darbat","na":"الخريف ووادي دربات","c":"ecology","s":"The monsoon that greens Dhofar","lat":17.11,"lng":54.45,"p":"Living today","dr":"Late June – September each year","el":"Dhofar escarpment, 50 minutes from Salalah","ic":"river","era":"N","t0":30,"t1":0,"te":"Arabia’s green season","ta":"موسم الخضرة في الجزيرة العربية","se":"Fog from the Indian Ocean turns the mountains green and fills the waterfalls of Wadi Darbat","sa":"ضباب من المحيط الهندي يخضّر الجبال ويملأ شلالات وادي دربات","desc":"From late June to September the south-west monsoon wraps the Dhofar mountains in fog and drizzle, with the landscape greenest from mid-July to the end of August; temperatures drop while the rest of Arabia is at about 43 °C. Wadi Darbat, about 50 minutes from Salalah, fills with waterfalls, lakes and grazing camels, and the escarpment's woodland of figs, olives and frankincense depends on this fog. The season draws thousands of visitors to Salalah each year.","sig":"The only monsoon forest ecosystem of the Arabian Peninsula.","ex":"Environment Authority, Oman; Oman Meteorology","disc":["Fog-fed woodland on the escarpment","Peak greenery mid-July to late August"],"refs":["Hasan, D. (2023). Everything you need to know about travelling to Salalah during khareef season. The National, 20 July 2023.","Oman Observer (2026). Early rains signal start of Dhofar's khareef season."],"conf":"","ev":"","an":"","val":""},{"id":"salut-bisya","n":"Salut (Husn and Qaryat Salut)","na":"سلوت (حصن سلوت وقرية سلوت)","c":"archaeological","s":"Bronze Age tower and Iron Age town near Bisya · Italian Mission to Oman","lat":22.8,"lng":57.29,"p":"Early Bronze Age to Iron Age (reused to the Islamic period)","dr":"3rd millennium BC – 1st millennium BC","el":"Twice-yearly excavation campaigns since 2004","ic":"mound","era":"P","t0":4525,"t1":2325,"te":"The hill where legends and layers meet","ta":"التلّ الذي تلتقي فيه الأساطير بالطبقات","se":"A fortified hill and a lower town near Bisya, dug since 2004 by an Italian mission, with a Bronze Age tower and an Iron Age settlement far larger than once thought","sa":"تلّ محصّن ومدينة سفلية قرب بسيا، تنقّب فيهما بعثة إيطالية منذ 2004، مع برج من العصر البرونزي ومستوطنة من العصر الحديدي أكبر بكثير مما كان يُظن","desc":"An ancient oasis on the Salut plain near Bisya in central Oman, first surveyed in the 1970s by Harvard University, the British Archaeological Expedition and the University of Birmingham, and excavated from 2004 by the Italian Mission to Oman (IMTO) led by Alessandra Avanzini. The mission rebuilt a collapsed Bronze Age tower, plastered the mud-brick walls for preservation and, after a decade of work, had restored the site's monumentality by 2015. Excavation of the lower settlement (Qaryat Salut) showed its inhabited area was much larger than previously thought, and very high radiocarbon dates from the upper fortified area (Husn Salut) point to a large central-Omani settlement by the end of the 2nd millennium BC with classic Iron Age material culture. Finds include pottery, soft-stone vessels, seals, bronze objects and terracotta figurines, presented in a Virtual Museum of Salut built by the mission.","sig":"Salut is the key excavated sequence for the Iron Age of central Oman, a region long overshadowed by sites in the UAE.","ex":"Italian Mission to Oman (University of Pisa, A. Avanzini) 2004–present; earlier surveys by Harvard, the British Archaeological Expedition and University of Birmingham","disc":["Iron Age lower town far larger than previously thought","Bronze Age tower rebuilt after collapse"],"refs":["Tagliamonte, E. & Avanzini, A. (2018). New data from the renewed excavation at Salūt: the Iron Age settlement (Qaryat Salūt). Proceedings of the Seminar for Arabian Studies 48, 339–353.","Oman Observer (2024). Salut: A glimpse into Oman's ancient heritage."],"conf":"","ev":"","an":"","val":""},{"id":"al-khashbah","n":"Al-Khashbah","na":"الخشبة","c":"archaeological","s":"Hafit-period towers with the oldest copper working in Oman · University of Tübingen","lat":22.67,"lng":58.05,"p":"Hafit period (Early Bronze Age)","dr":"About 3200 – 2800 BC","el":"Building V dated to about 3200 cal. BC","ic":"flame","era":"P","t0":5225,"t1":4825,"te":"Where Oman first smelted copper","ta":"حيث صُهر النحاس في عُمان أول مرة","se":"One of the largest Early Bronze Age sites in Oman, 17 km north of Sinaw, whose stone tower holds the oldest substantial evidence of copper processing in the country","sa":"أحد أكبر مواقع العصر البرونزي المبكر في عُمان، على بعد 17 كم شمال سناو، يضم برجه الحجري أقدم دليل جوهري على معالجة النحاس في البلاد","desc":"Al-Khashbah, about 17 km north of Sinaw, is one of Oman's largest Early Bronze Age sites. The University of Tübingen excavated there for four seasons from 2015 to 2018 and uncovered Hafit-period architecture including a mud-brick complex (Building I, dated to about 2800 cal. BC) with bead and chipped-stone workshops, resembling the contemporary tower at Hili 8, and a stone tower (Building V) dated to about 3200 cal. BC. Building V holds the oldest substantial evidence of copper processing in Oman, which the excavators link to archaic Uruk texts that mention copper objects from the Arabian Gulf. The site has three Hafit-period stone towers and six Umm an-Nar-period towers, and the project, funded by the German Research Foundation, combined field, aerial and geophysical surveys with excavation.","sig":"It pushes the beginning of Omani copper metallurgy, the basis of the land of Magan, back to the end of the 4th millennium BC.","ex":"University of Tübingen (C. Schmidt, S. Döpper), 2015–2018","disc":["Oldest substantial copper processing in Oman, c. 3200 BC","Mud-brick complex with bead workshops, c. 2800 BC"],"refs":["Schmidt, C. & Döpper, S. (2019). The Hafit period at Al-Khashbah, Sultanate of Oman: results of four years of excavations and material studies. Proceedings of the Seminar for Arabian Studies 49, 265–274.","Schmidt, C. & Döpper, S. (2017). The development of complexity at third-millennium BC al-Khashbah, Sultanate of Oman: results of the first two seasons, 2015 and 2016. Proceedings of the Seminar for Arabian Studies 47, 215–227."],"conf":"","ev":"","an":"","val":""},{"id":"ras-al-hamra-rh5","n":"Ras al-Hamra RH-5","na":"رأس الحمراء (الموقع RH-5)","c":"archaeological","s":"Neolithic fishing village and shell midden in Muscat · Italian Archaeological Mission","lat":23.63,"lng":58.5,"p":"Neolithic (Middle Holocene)","dr":"Late 5th – end of 4th millennium BC","el":"374 stone and shell beads recovered","ic":"shell","era":"P","t0":6325,"t1":5025,"te":"Fisherfolk on the red headland","ta":"صيّادون على الرأس الأحمر","se":"A shell-midden village on a promontory at Qurm, Muscat, where Neolithic fisher-gatherers lived year-round and buried their dead in a large cemetery","sa":"قرية من أكوام الأصداف على رأس بحري في القرم بمسقط، عاش فيها صيادون وجامعو أصداف من العصر الحجري الحديث طوال العام ودفنوا موتاهم في مقبرة كبيرة","desc":"RH-5 is a shell-midden settlement on a large promontory in the Qurm area of Muscat, excavated by the Italian Archaeological Mission in Oman with the support of the Ministry of Heritage and Tourism. It dates from the late 5th to the end of the 4th millennium BC and consists of superimposed food refuse from fishing, shell collecting, hunting and herding, together with dwellings, household installations, everyday objects and ornaments. Exploiting several ecological niches allowed year-round sedentary occupation. The excavations recovered 374 beads of stone and marine shell, and the site includes a large cemetery.","sig":"It is the reference site for the fisher-gatherer way of life that the excavators see as a key step in the neolithisation of Oman.","ex":"Italian Archaeological Mission in Oman (P. Biagi; later L. G. Marcucci, É. Badel, F. Genchi), Ministry of Heritage and Tourism","disc":["Year-round Neolithic village of fisherfolk","374 stone and shell beads"],"refs":["Marcucci, L. G., Badel, É. & Genchi, F. (2021). Prehistoric fisherfolk of Oman: the Neolithic village of Ras Al-Hamra RH-5. Archaeopress, Oxford.","Pisan, A., Biagi, P. & Gasparotto, G. Stone and shell beads from the shell-midden settlement RH-5, Muscat (Sultanate of Oman). Harappa.com."],"conf":"","ev":"","an":"","val":""},{"id":"lizq-fort","n":"Lizq Iron Age Fort (L1)","na":"حصن لزق من العصر الحديدي","c":"archaeological","s":"Largest Early Iron Age hill fort in central Oman · German Mining Museum survey","lat":22.7,"lng":58.18,"p":"Early Iron Age (Lizq-Rumaylah period)","dr":"Early 1st millennium BC","el":"Fort surface of more than 20,000 m²","ic":"wall","era":"P","t0":3300,"t1":2300,"te":"A staircase up a mountain of stone","ta":"درج يصعد جبلاً من الحجر","se":"A ruined stone fort about 175 m wide on a mountain top near the Lizq palm garden, reached by a stair up its northern face","sa":"حصن حجري متهدّم بعرض نحو 175 م على قمة جبل قرب بستان نخيل لزق، يُصعد إليه بدرج على واجهته الشمالية","desc":"The fort known as L1 stands on a mountain about 1,000 m south-east of the Lizq palm garden in Ash Sharqiyah North. The main fort on the western peak is about 175 m wide with a surface of more than 20,000 m², and stairs lead up the northern face of the mountain. Gerd Weisgerber of the German Mining Museum in Bochum discovered it in 1979, guided by Shaikh Hamdan al-Harthy of Samad, and in 1981 a single-season German team under Stephan Kroll mapped the site, carried out a small rescue excavation and restored the northern stairs. Kroll compared its pottery with Iron Age pottery from Iran; no falaj was found and the associated village has not been located.","sig":"It is described as the largest Early Iron Age fort in central Oman.","ex":"German Mining Museum, Bochum (G. Weisgerber 1979; S. Kroll 1981)","disc":["Discovered 1979, mapped 1981","Stone stairway up the northern face"],"refs":["Kroll, S. (2013). The Early Iron Age Lizq Fort, Sultanate of Oman. Zeitschrift für Archäologie Außereuropäischer Kulturen 5.","Wikipedia contributors (2026). Lizq, citing Kroll (1998, 2013) and Yule (2001)."],"conf":"","ev":"","an":"","val":""},{"id":"samad-al-shan","n":"Samad al-Shan","na":"سمد الشأن","c":"archaeological","s":"Type-site of the Samad Late Iron Age · about 260 graves documented","lat":22.8,"lng":58.15,"p":"Samad Late Iron Age","dr":"About 300 BC – AD 300","el":"About 260 graves, Bronze Age to Late Iron Age","ic":"sword","era":"H","t0":2325,"t1":1725,"te":"Graves that named a period","ta":"قبور أعطت اسمها لحقبة","se":"An oasis cemetery in Sharqiyah where German excavations defined the non-writing Late Iron Age culture of central Oman","sa":"مقبرة واحة في الشرقية حدّدت فيها التنقيبات الألمانية ثقافة العصر الحديدي المتأخر غير الكاتبة في وسط عُمان","desc":"Samad al-Shan is an oasis about 2 km east of al-Maysar in Sharqiyah at 565 m altitude, discovered in part by British surveyors in 1976. From 1981 Gerd Weisgerber of the German Mining Museum in Bochum mapped it, and Burkhard Vogt, Weisgerber and Paul Yule excavated there; by the end of the project in 1995 about 210 of some 360 Late Iron Age graves had been investigated, and roughly 260 graves from the Bronze Age to the Late Iron Age were documented. The Samad assemblage, now known from 126 sites, is dated by absolute methods to about 300 BC – AD 300. Mature men were usually laid on the right side and women on the left; men's graves hold arrowheads, daggers and swords, women's never contain weapons, and imported glazed perfume bottles and lathe-turned soft-stone bowls appear with hand-made local pottery.","sig":"The site gives its name to the Late Iron Age of central Oman, a period otherwise without writing.","ex":"German Mining Museum, Bochum, later University of Heidelberg (G. Weisgerber, B. Vogt, P. Yule), 1981–1995","disc":["About 210 of 360 Late Iron Age graves excavated","Men buried on the right, women on the left"],"refs":["Yule, P. (2001). Die Gräberfelder in Samad al-Shan (Sultanat Oman). Materialien zu einer Kulturgeschichte. Rahden.","Yule, P. (2008). Sasanian Presence and Late Iron Age Samad in Central Oman, some Corrections. Heidelberg University.","Wikipedia contributors (2026). Samad al-Shan, citing Yule (2001, 2016, 2018)."],"conf":"","ev":"","an":"","val":""},{"id":"nizwa-fort","n":"Nizwa Fort","na":"قلعة نزوى","c":"archaeological","s":"17th-century round tower of the Ya’ariba imams · Nizwa","lat":22.93,"lng":57.53,"p":"Islamic (Ya’ariba imamate)","dr":"1650s AD, on 12th-century foundations","el":"Tower about 36 m across and 30 m high","ic":"wall","era":"H","t0":376,"t1":250,"te":"A drum of stone over an underground stream","ta":"أسطوانة من حجر فوق جدول تحت الأرض","se":"A huge round tower built in the 1650s under Imam Sultan bin Saif, filled with rubble and ringed by 480 gun-ports","sa":"برج دائري ضخم بُني في خمسينيات القرن السابع عشر في عهد الإمام سلطان بن سيف، مملوء بالردم ومحاط بـ480 فتحة للبنادق","desc":"Nizwa Fort was built in the 1650s under Imam Sultan bin Saif, the second Ya'rubi ruler, over an underlying structure of the 12th century; the main work took about 12 years. The round tower is about 36 m in diameter and 30 m high (official tourism figures give 45 m and 34 m), its foundations go about 30 m into the ground, and part of it is filled with rocks, dirt and rubble above an underground stream. Defences include murder holes above the doors, about 24 openings for mortar fire, 480 gun-ports, 24 original cannons of which four remain, pitfalls in the twisting stair and cellars for food and munitions. One cannon from Boston was presented to the first Omani ambassador to the United States in 1840.","sig":"It is the best-known of Oman's forts and the seat from which the Ya'ariba imams ruled the interior.","ex":"Built under Imam Sultan bin Saif al-Ya’rubi; managed as a heritage site by Oman (Omran)","disc":["Took about 12 years to build","480 gun-ports and 24 cannon positions"],"refs":["Wikipedia contributors (2026). Nizwa Fort, citing Experience Oman, Walker (Lonely Planet 2007) and Cox, P. (1925) The Geographical Journal 66(3).","Experience Oman (Ministry of Heritage and Tourism). Nizwa Fort."],"conf":"","ev":"","an":"","val":""},{"id":"jabrin-castle","n":"Jabrin Castle","na":"قلعة جبرين","c":"archaeological","s":"Painted-ceiling palace of Imam Bilarab bin Sultan · Bahla","lat":22.92,"lng":57.26,"p":"Islamic (Ya’ariba imamate)","dr":"Built 1670 AD","el":"5 floors and 55 rooms","ic":"jar","era":"H","t0":356,"t1":200,"te":"A palace of painted ceilings","ta":"قصر السقوف المزخرفة","se":"A five-storey palace of plastered sandstone built in 1670 by Imam Bilarab bin Sultan, famed for ceilings painted with calligraphy and a Sun and Moon room with 14 windows","sa":"قصر من خمسة طوابق من الحجر الرملي المُجصّص بناه الإمام بلعرب بن سلطان عام 1670، يشتهر بسقوفه المزخرفة بالخط العربي وبغرفة الشمس والقمر ذات الـ14 نافذة","desc":"Jabrin Castle stands among farms in the Wilayat of Bahla, Al Dakhiliyah. It was built in 1670 by Imam Bilarab bin Sultan bin Saif al-Ya'rubi, third of the Ya'ariba imams, from grey sandstone covered in thick plaster, with five floors and 55 rooms around two courtyards 16 and 22 m high, each with a well more than 20 m deep. Many rooms have ceilings painted with Arabic calligraphy; the Sun and Moon room has 14 windows, the upper ones admitting moonlight and the lower controlling daylight, and the imam's protection room contains four secret trenches. Two towers defended it, a falaj waters the orchards, and it served first as the imam's palace and later as a seat of government; it also held a library, a courtroom and a classroom for Quran lessons, and the imam was buried in a corner of the ground floor.","sig":"It is the finest example of Omani palace decoration from the Ya'ariba period.","ex":"Built under Imam Bilarab bin Sultan; open daily as a heritage site","disc":["Ceilings painted with calligraphy","Sun and Moon room with 14 windows"],"refs":["Oman Observer (2024). Jabreen Castle's painted ceilings attract visitors.","Oman Observer (2017). The Persistence of Jabreen Castle."],"conf":"","ev":"","an":"","val":""},{"id":"al-hoota-cave","n":"Al Hoota Cave","na":"كهف الهوتة","c":"geological","s":"5 km karst cave with an underground lake and blind fish · show cave since 2006","lat":23.08,"lng":57.35,"p":"Karst in Cretaceous limestone of the Hajar","dr":"About 2 million years old","el":"Cave system about 5 km long","ic":"cliff","era":"D","t0":2000000,"t1":0,"te":"Blind fish in the dark","ta":"أسماك عمياء في الظلام","se":"A 5 km cave at the foot of Jebel Shams, believed to be 2 million years old, whose lake is home to the Omani blind cave fish","sa":"كهف بطول 5 كم عند سفح جبل شمس يُعتقد أن عمره مليونا سنة، تعيش في بحيرته سمكة الكهف العُمانية العمياء","desc":"Al Hoota Cave lies at Al Hamra in Ad Dakhiliyah at the foot of Jebel Shams. The karst system is about 5 km long, of which 4.5 km is show cave, with its highest point about 65 m above the entrance; it is believed to be about two million years old and opened to visitors in 2006 with electric lighting and a guided walk of 500 m ending at an underground lake 800 m long. The lake holds the Omani blind cave fish (Garra barreimiae), whose adults lose their eyesight, and the cave shelters more than 100 animal species including bats, hunter spiders and water beetles. Its stalagmites have been used for palaeoclimate research, including a 2022 Science study on droughts in late antique Arabia.","sig":"It is Oman's only developed show cave and a natural archive of past climate.","ex":"Managed as a show cave (opened 2006); stalagmites studied by D. Fleitmann et al.","disc":["Underground lake 800 m long","Stalagmites record ancient droughts"],"refs":["Fleitmann, D. et al. (2022). Droughts and societal change: The environmental context for the emergence of Islam in late antique Arabia. Science 376, 1317–1321.","Wikipedia contributors (2026). Al Hoota Cave, citing BBC (2012) and Toronto Star (2009)."],"conf":"","ev":"","an":"","val":""},{"id":"bimmah-sinkhole","n":"Bimmah Sinkhole (Hawiyat Najm)","na":"هوية نجم (بلعة بمّه)","c":"geological","s":"Collapse sinkhole in coastal limestone · Hawiyat Najm Park","lat":23.04,"lng":59.07,"p":"Karst collapse in limestone","dr":"Quaternary","el":"About 50 by 70 m wide and 20 m deep","ic":"sinkhole","era":"D","t0":1000000,"t1":0,"te":"The well of the falling star","ta":"بئر النجم الساقط","se":"A sinkhole 50 by 70 m across and 20 m deep, 600 m from the sea, formed when the roof of dissolved limestone collapsed; locals once blamed a meteorite","sa":"بلعة بعرض 50 في 70 م وعمق 20 م على بعد 600 م من البحر، تكوّنت عندما انهار سقف الحجر الجيري المذاب؛ وكان الأهالي يعزونها إلى نيزك","desc":"Hawiyat Najm, 'the deep well of the falling star', lies between Dibab and Bimmah on the Muscat–Sur highway, about 600 m from the sea. The sinkhole is roughly 50 m by 70 m across and about 20 m deep, and formed when the surface layer collapsed as the underlying limestone dissolved. The name records a local belief that a meteorite made it. The municipality has developed Hawiyat Najm Park around it, fenced, with a stairway down to the water.","sig":"It is the most accessible example of karst collapse on Oman's eastern coast.","ex":"Hawiyat Najm Park (local municipality); limestone mapped by S. Rajendran & S. Nasir (2014)","disc":["Roof collapse over dissolved limestone","Named for a supposed fallen star"],"refs":["Rajendran, S. & Nasir, S. (2014). ASTER mapping of limestone formations and study of caves, springs and depressions in parts of Sultanate of Oman. Environmental Earth Sciences 71(1), 133–146.","Wikipedia contributors (2026). Bimmah Sinkhole, citing Oman Ministry of Tourism."],"conf":"","ev":"","an":"","val":""},{"id":"duqm-rock-garden","n":"Duqm Rock Garden","na":"حديقة الصخور بالدقم","c":"geological","s":"Wind-sculpted limestone and sandstone about 40 million years old · Al Wusta","lat":19.66,"lng":57.7,"p":"Eocene limestone and sandstone","dr":"About 40 million years","el":"About 6 km² of sculpted rock","ic":"cliff","era":"D","t0":40000000,"t1":0,"te":"Statues carved by the wind","ta":"تماثيل نحتتها الرياح","se":"Six square kilometres of limestone and sandstone laid down some 40 million years ago and eroded by wind and water into statue-like forms","sa":"ستة كيلومترات مربعة من الحجر الجيري والرملي ترسّبت قبل نحو 40 مليون سنة ونحتتها الرياح والمياه في أشكال تشبه التماثيل","desc":"The Rock Garden lies in the centre of Duqm, about 550 km from Muscat, inside the Special Economic Zone at Duqm. It covers about 6 km² of sandstone and limestone in which fragile limestone deposits, formed roughly 40 million years ago, are capped by a harder layer; wind and water erosion over millions of years sculpted them into symmetrical, statue-like forms. The site is fenced with visitor gates, parking and surveillance cameras and is run by the zone authority's Technical Affairs Department, which in 2024 commissioned a study for walkways and lighting. Admission is free.","sig":"It is described as one of the most important geological sites in Oman.","ex":"Special Economic Zone at Duqm (SEZAD), Technical Affairs Department","disc":["Hard cap over soft limestone","Fenced and protected by SEZAD"],"refs":["Oman Observer (2024). Duqm Rock Garden: A geological marvel, tourist oasis.","Wikipedia contributors (2026). Duqm Rock Garden, citing Times of Oman and Oman Observer (2017)."],"conf":"","ev":"","an":"","val":""},{"id":"khor-ash-sham","n":"Khor Ash Sham","na":"خور الشم","c":"geological","s":"Drowned valley of the sinking Musandam peninsula · 16 km long","lat":26.2,"lng":56.32,"p":"Jurassic Musandam Group limestone, drowned by Neogene subsidence","dr":"Collision began about 5 million years ago","el":"Peninsula sinking about 6 mm a year","ic":"wave","era":"D","t0":5000000,"t1":0,"te":"Fjords without ice","ta":"مضايق بلا جليد","se":"A 16 km inlet walled by 800 m cliffs, a river valley drowned as the Arabian plate bends down under Eurasia at 6 mm a year","sa":"خور بطول 16 كم تحيط به جروف بارتفاع 800 م، وادٍ نهري غمره البحر مع انثناء الصفيحة العربية تحت الصفيحة الأوراسية بمعدل 6 مم في السنة","desc":"Khor Ash Sham is the longest of the Musandam inlets, about 16 km long with walls rising about 800 m from the water. The inlets are rias, drowned river valleys that resemble fjords but were never carved by ice, since no glaciers have covered the Arabian Peninsula since the Permian; the peninsula is subsiding at about 6 mm a year as the Arabian lithosphere is flexed down beneath the Eurasian plate, in a collision that began about 5 million years ago. The cliffs are Jurassic Musandam Group carbonates about 1,500 m thick, with the Upper Triassic Ghalilah Formation exposed at sea level, and the Hagab Thrust records about 15 km of shortening. Telegraph Island in the inlet carries the foundations of a British cable repeater station built in 1865 and abandoned in 1868, and the khor has a healthy dolphin population.","sig":"It is the clearest place in Arabia to see a continent being pulled down into a plate collision.","ex":"Geology described by L. Abbott & T. Cook (GeoExpro 2020)","disc":["Subsidence of about 6 mm a year","Cliffs of Jurassic limestone 800 m high"],"refs":["Abbott, L. & Cook, T. (2020). Oman's Musandam Peninsula: Geodynamic and Geopolitical Nexus. GeoExpro.","Rough Guides. The khors and Kumzar: Khor Ash Sham."],"conf":"","ev":"","an":"","val":""},{"id":"jebel-misht","n":"Jebel Misht","na":"جبل مشط","c":"geological","s":"Oman Exotic limestone block with a 1,000 m south face · Wadi al-Ayn","lat":23.22,"lng":57.12,"p":"Permian–Triassic Oman Exotic limestone, thrust onto Arabia in the Late Cretaceous","dr":"About 260 – 65 million years","el":"South face over 1,000 m high","ic":"cliff","era":"D","t0":260000000,"t1":65000000,"te":"A reef that sank, then rose","ta":"شعاب غرقت ثم ارتفعت","se":"A 2,090 m comb-shaped mountain of exotic limestone, a sunken reef platform carried onto Arabia when the Tethys closed, with a near-vertical face over 1,000 m","sa":"جبل على شكل مشط بارتفاع 2,090 م من الحجر الجيري الدخيل، منصة شعابية غارقة حُملت على شبه الجزيرة العربية عند انغلاق محيط تيثس، بواجهة شبه عمودية تتجاوز 1,000 م","desc":"Jebel Misht, 'Comb Mountain', rises to 2,090 m above Wadi al-Ayn about 50 km north-west of Nizwa, with a south face of over 1,000 m rising almost vertically. It is made of Oman Exotic Limestone, a block out of sequence with the surrounding rocks that was thrust onto Arabia when the Tethys Ocean closed about 65 million years ago. The Oman Exotics are limestones caught up in the thrust stack beneath the Semail Ophiolite; the Middle–Late Permian ones were reef build-ups on platforms that sank to ocean depths during rifting and were later engulfed by basalts, and carry foraminifera, calcareous algae, corals and crinoids. Michael Searle, Peter King and Philip Davis made the first recorded ascent by the west ridge on 11–12 February 1982, and the south face was climbed in February 1983.","sig":"It is the most dramatic of Oman's exotic blocks, a piece of Tethyan sea floor standing on the desert edge.","ex":"Geology by M. P. Searle; Permian exotics studied by O. Abdelghany, A. R. Fowler & W. Hashem (2019)","disc":["Exotic limestone out of sequence with its surroundings","First climbed 1982"],"refs":["Searle, M. P. (1985). Arabian Fantasy – Jebel Misht. American Alpine Journal.","Abdelghany, O., Fowler, A. R. & Hashem, W. (2019). Oman Exotic limestones in the UAE-Oman border area with implications for Middle-Upper Permian Neo-Tethyan rifting. Journal of Asian Earth Sciences 181, 103879."],"conf":"","ev":"","an":"","val":""},{"id":"barr-al-hikman","n":"Barr Al Hikman","na":"بر الحكمان","c":"ecology","s":"Largest shorebird wetland in the Middle East · Ramsar site 2529","lat":20.56,"lng":58.43,"p":"Intertidal mudflats, seagrass and coral","dr":"Nature reserve 2014 · Ramsar 2023","el":"464,887 waterbirds counted in January 2016","ic":"bird","era":"N","t0":12,"t1":0,"te":"Half a million birds on the mud","ta":"نصف مليون طائر على الطين","se":"A 2,137 km² peninsula of mudflats, seagrass and reef on the Arabian Sea where up to half a million waterbirds from Arctic Russia and Central Asia winter","sa":"شبه جزيرة بمساحة 2,137 كم² من المسطحات الطينية والأعشاب البحرية والشعاب على بحر العرب، يشتو فيها حتى نصف مليون طائر مائي قادم من روسيا القطبية وآسيا الوسطى","desc":"Barr Al Hikman in Mahout, Al Wusta, about 400 km south of Muscat, was made a nature reserve by Royal Decree 51/2014 and designated Ramsar site 2529 on 25 October 2023 with an area of 213,715 ha. A January 2016 count recorded 464,887 waterbirds, including 125,659 dunlin, 123,369 lesser sandplover and 60,976 bar-tailed godwit, and 18 species exceed 1% of their flyway populations; it is described as the most significant wintering wetland in the Middle East. Its Halodule and Halophila seagrass beds are the largest in Oman, with about 1,500 ha of coral reef and 200 ha of Avicennia mangrove, and the waters are used by the endangered Arabian Sea humpback whale and green and hawksbill turtles. Ten years of surveys by Wetlands International with Radboud University, Groningen, NIOZ and Sultan Qaboos University produced the 2018 book 'Barr Al Hikman: shorebird paradise in Oman'.","sig":"It is the single most important stop on the West Asian–East African flyway for Arctic-breeding shorebirds.","ex":"Environment Authority (Nature Reserves Section); Wetlands International, Radboud University, University of Groningen, NIOZ, Sultan Qaboos University","disc":["464,887 waterbirds in one January count","Largest seagrass beds in Oman"],"refs":["Ramsar Convention (2023). Information Sheet on Ramsar Wetlands: Wetlands Reserve in Al Wusta Governorate (Barr Al Hikman), site 2529.","de Fouw, J., Bom, R., Thorpe, A., Klaassen, R. & Hagemeijer, W. (2018). Barr Al Hikman: shorebird paradise in Oman. Wetlands International."],"conf":"","ev":"","an":"","val":""},{"id":"qurm-nature-reserve","n":"Qurm Nature Reserve","na":"محمية القرم الطبيعية","c":"ecology","s":"Grey-mangrove reserve inside Muscat · Ramsar site 2144","lat":23.62,"lng":58.48,"p":"Avicennia marina mangrove and tidal creek","dr":"Reserve 1975 · Ramsar 2013","el":"194 bird species recorded","ic":"mangrove","era":"N","t0":51,"t1":0,"te":"A forest in the capital","ta":"غابة في العاصمة","se":"About 172 ha of grey mangrove in the heart of Muscat, protected since 1975, with 194 bird, 40 fish, 27 crustacean and 48 mollusc species","sa":"نحو 172 هكتاراً من أشجار القرم الرمادي في قلب مسقط، محمية منذ 1975، تضم 194 نوعاً من الطيور و40 من الأسماك و27 من القشريات و48 من الرخويات","desc":"Qurm Nature Reserve lies within the urban area of Qurm in Bawshar, Muscat, on the Sea of Oman, and takes its name from the grey mangrove (Avicennia marina) that dominates it. It was established in 1975 by decree of Sultan Qaboos, recognised as an Important Bird Area in 1994, and its lower 106.8 ha were designated Ramsar site 2144 on 19 April 2013; the whole reserve covers about 172 ha. The Ramsar record lists 194 bird species, more than 40 fish species including commercial ones, 27 crustaceans and 48 molluscs, and calls it one of the largest mangrove areas on the east coast of the Arabian Peninsula. It is being developed as a conservation and education site with a visitor centre.","sig":"It is the largest natural mangrove stand on Oman's northern coast and a nursery for the capital's fisheries.","ex":"Environment Authority of Oman; vegetation studied by H. Kürschner (1986)","disc":["Protected since 1975","106.8 ha Ramsar site inside the city"],"refs":["Ramsar Sites Information Service. Qurm Nature Reserve, site 2144 (2013).","Kürschner, H. (1986). A Study of the Vegetation of the Qurm Nature Reserve. Arab Gulf Journal of Scientific Research.","Wikipedia contributors (2026). Qurm Nature Reserve, citing RSIS and BirdLife International."],"conf":"","ev":"","an":"","val":""},{"id":"wadi-sireen-reserve","n":"Al Sireen (Wadi Sareen) Nature Reserve","na":"محمية السرين الطبيعية","c":"ecology","s":"Arabian tahr stronghold in the Eastern Hajar · UNESCO biosphere reserve 2025","lat":23.22,"lng":58.72,"p":"Mountain cliffs and rocky slopes","dr":"Reserve since 1975","el":"103,888 ha, over 400 plant species","ic":"gazelle","era":"N","t0":51,"t1":0,"te":"The shy goat of the cliffs","ta":"تيس الجروف الخجول","se":"A 1,039 km² mountain reserve 45 km south-west of Muscat set up in 1975 for the Arabian tahr, with 400 plant species, ten of them endemic","sa":"محمية جبلية بمساحة 1,039 كم² على بعد 45 كم جنوب غرب مسقط أُنشئت عام 1975 للطهر العربي، فيها 400 نوع نباتي عشرة منها متوطنة","desc":"Al Sireen Nature Reserve was set up in 1975 in the Eastern Hajar about 45 km south-west of Muscat, bordering the wilayats of Al Amerat, Qurayat and Dima wa Tayeen, with entry points at Jabal Aswad and Jabal Abyad. It covers 103,888 ha and is an IUCN Category II protected area. Its flagship species is the Arabian tahr, the smallest of the ibex-like goats, which hides among large rocks, can go two or three days without drinking and is threatened by poaching and urban expansion; Arabian gazelle, Arabian wolf, red fox, Egyptian vulture and the Oman saw-scaled viper also live there, with about 400 plant species including ten endemic and four endangered. In September 2025 UNESCO's MAB council added it, with Al Jabal al Akhdar, to the World Network of Biosphere Reserves, Oman's first; about 2,533 people live in its buffer zone.","sig":"It is the main protected refuge of the endangered Arabian tahr, found only in the Hajar mountains.","ex":"Environment Authority of Oman (Office for the Conservation of the Environment); UNESCO MAB","disc":["Reserve since 1975, biosphere reserve 2025","Ten endemic plant species"],"refs":["Oman Observer (2024). Want to see a rare and shy animal? Come to Al Sireen Reserve.","Oman Observer (2025). Two Omani reserves listed on UNESCO's biosphere programme."],"conf":"","ev":"","an":"","val":""},{"id":"khawrs-salalah-coast","n":"Khawrs of the Salalah Coast","na":"أخوار ساحل صلالة","c":"ecology","s":"Nine coastal lagoons protected since 1997 · Dhofar","lat":17.03,"lng":54.38,"p":"Brackish coastal lagoons with reed and mangrove","dr":"Protected June 1997","el":"More than 160 bird species recorded","ic":"bird","era":"N","t0":29,"t1":0,"te":"Lagoons behind the beach","ta":"بحيرات خلف الشاطئ","se":"A chain of nine brackish lagoons along the Dhofar coast, from Mughsayl to Khawr Rori, where migrants from Africa, Europe and India rest among reeds and mangroves","sa":"سلسلة من تسعة أخوار قليلة الملوحة على ساحل ظفار من المغسيل إلى خور روري، تستريح فيها الطيور المهاجرة من أفريقيا وأوروبا والهند بين القصب وأشجار القرم","desc":"The Dhofar government's protected region covers nine wetlands: Khawr Mughsayl, Khawr Dahareez, Khawr Baleed, Khawr Awqad, Khawr Sawli, Khawr Taqah, Khawr Rawri, Khawr Qurm al Sagheer and Khawr Qurm al Kabeer, declared protected in June 1997. They range from a few hectares to more than a hundred: Khawr Mughsayl is about 3 km long and 150 m wide, Khawr Awqad about 16 ha and Khawr Taqah about 2 km². More than 160 bird species have been recorded, the lagoons being important stopovers for migrants, with milkfish and mullet that tolerate changing salinity, reed-mace (Typha) and mangroves, which are being planted to give cover for birds. The management plan allows controlled fodder cutting and limited visitor facilities and protects the archaeological sites beside them.","sig":"Together the khawrs are the main freshwater-influenced bird habitat on Oman's monsoon coast.","ex":"Environment Authority of Oman (Dhofar); BirdLife International Important Bird Areas","disc":["Nine lagoons protected in 1997","More than 160 bird species"],"refs":["Oman Observer (2024). Rich biodiversity stored in 'khwars' of Dhofar.","Wikipedia contributors (2026). Khawrs of the Salalah Coast Reserve."],"conf":"","ev":"","an":"","val":""},{"id":"arabian-sea-humpback","n":"Hallaniyat Bay and the Arabian Sea humpback whale","na":"خليج الحلانيات والحوت الأحدب في بحر العرب","c":"ecology","s":"Only non-migrating humpback population, fewer than 100 whales · Dhofar","lat":17.55,"lng":55.8,"p":"Arabian Sea upwelling waters","dr":"Surveys since 2000","el":"About 82 whales (95% CI 60–111)","ic":"dolphin","era":"N","t0":26,"t1":0,"te":"The whales that never left","ta":"الحيتان التي لم ترحل قط","se":"A tiny, isolated humpback population off Dhofar and the Gulf of Masirah that breeds and feeds in the same waters year-round and is now proposed as a fourth subspecies","sa":"مجموعة صغيرة معزولة من الحيتان الحدباء قبالة ظفار وخليج مصيرة تتكاثر وتتغذى في المياه نفسها طوال العام، ويُقترح الآن اعتبارها نويعاً رابعاً","desc":"The Oman Arabian Sea Important Marine Mammal Area covers 96,146 km² and holds the Arabian Sea humpback whale, estimated by mark-recapture at 82 individuals (95% CI 60–111) from 2000–2004 photo-identification, the basis of its IUCN Endangered listing. Satellite tags on 14 whales in 2014–2015 showed strong fidelity to two hotspots, Dhofar (Hallaniyat Bay), linked to reproduction, and the Gulf of Masirah, linked to feeding; at least 20 cetacean species use the area, including blue, Bryde's and sperm whales. Unlike other humpbacks they do not migrate. A 2026 study in Frontiers in Marine Science led by the Wildlife Conservation Society and the Environment Society of Oman, analysing mitochondrial DNA from 2,285 whales, found the population diverged 43,000–113,000 years ago, has the lowest genetic diversity of any humpback region and merits recognition as a fourth subspecies; threats include fishing-gear entanglement, vessel strikes and noise.","sig":"It is the world's only resident, non-migratory humpback whale population, and one of its smallest.","ex":"Environment Society of Oman; Wildlife Conservation Society; IUCN Marine Mammal Protected Areas Task Force","disc":["About 82 whales, isolated for up to 113,000 years","Breed and feed in the same waters all year"],"refs":["Amaral, R. et al. (2026). Arabian Sea humpback whales as a distinct evolutionary lineage. Frontiers in Marine Science.","IUCN Marine Mammal Protected Areas Task Force (2021). Oman Arabian Sea IMMA factsheet, citing Minton et al. (2008, 2011).","The National (2026). Arabian whales found to be genetically distinct from other humpbacks."],"conf":"","ev":"","an":"","val":""},{"id":"al-saleel-park","n":"Al Saleel Natural Park","na":"منتزه السليل الطبيعي","c":"ecology","s":"Acacia woodland and Arabian gazelle herds · Al Kamil wal Wafi","lat":22.36,"lng":59.2,"p":"Samr (Acacia tortilis) savanna on gravel plain","dr":"Reserve since 1997","el":"220 km² of acacia woodland","ic":"plant","era":"N","t0":29,"t1":0,"te":"Gazelles under the umbrella thorns","ta":"غزلان تحت السمر","se":"A 220 km² acacia plain in Sharqiyah, protected in 1997, where Arabian gazelle herds have recovered from over-hunting among 57 bird and 166 insect species","sa":"سهل من السمر بمساحة 220 كم² في الشرقية حُمي عام 1997، تعافت فيه قطعان الغزال العربي من الصيد الجائر وسط 57 نوعاً من الطيور و166 من الحشرات","desc":"Al Saleel Natural Park lies at Al Kamil wal Wafi in Ash Sharqiyah, bounded by a mountain range to the north, a plain reaching the Gehwan reserve to the east and Wadi Al Bathaa and the Sharqiya Sands to the south. Set up in 1997, it covers 220 km² predominantly forested with samr (umbrella thorn acacia) and salam (Acacia ehrenbergiana) among more than 100 plant species. Its Arabian gazelle, once sharply reduced by over-hunting, are now seen in large herds thanks to local cooperation against poaching; the reserve also records about 57 bird species including steppe eagle, Arabian ibex, red fox, Cape hare, eight reptiles and 166 insect species, and the Omani wild cat is listed among its rare species. Visitors need a permit from the Environment Authority.","sig":"It protects the largest acacia woodland of eastern Oman and one of the country's main gazelle populations.","ex":"Environment Authority of Oman","disc":["220 km² of samr acacia","Gazelle herds recovered after poaching controls"],"refs":["Oman Observer (2022). Al Saleel Natural Park: A safe home to Oman's Arabian gazelle.","Wikipedia contributors (2026). Al Saleel National Park, citing Protected Planet."],"conf":"","ev":"","an":"","val":""},{"id":"jebel-akhdar-saiq","n":"Al Jabal Al Akhdar and the Saiq Plateau","na":"الجبل الأخضر وهضبة سيق","c":"ecology","s":"Terraced rose gardens at 2,000 m · UNESCO biosphere reserve 2025","lat":23.07,"lng":57.65,"p":"Limestone massif with Mediterranean-type climate","dr":"Sanctuary 2011 · Biosphere reserve 2025","el":"Saiq plateau at about 2,000 m","ic":"plant","era":"N","t0":15,"t1":0,"te":"Roses on the green mountain","ta":"ورود على الجبل الأخضر","se":"A high limestone plateau where falaj-fed terraces grow roses for rosewater, pomegranates and walnuts, home to wild olive, Arabian ibex and 71 bird species","sa":"هضبة جيرية عالية تروي أفلاجها مدرّجات الورد لصناعة ماء الورد والرمان والجوز، وتعيش فيها الزيتون البري والوعل العربي و71 نوعاً من الطيور","desc":"Al Jabal Al Akhdar in Ad Dakhiliyah is a mostly limestone massif about 150 km from Muscat whose Saiq plateau lies at about 2,000 m. Its mild, Mediterranean-type climate and mountain springs feed falaj channels and a centuries-old terrace system that grows roses for traditional rosewater, pomegranates, walnuts, apricots, grapes and peaches, and it is a major area for honey-bee breeding; rock-art figures about 6,000 years old have been studied on the mountain. In August 2011 a decree created the Jebel Akhdar Sanctuary for Natural Sceneries, and in September 2025 UNESCO's MAB council listed the Al Jabal al Akhdar Landscape, about 4,500 ha, as a biosphere reserve for its rare wild olive trees, threatened Arabian ibex and Arabian wolf and more than 71 bird species including Egyptian vulture and golden eagle.","sig":"It is Oman's highland agricultural heartland and, with Al Sireen, its first UNESCO biosphere reserve.","ex":"Environment Authority of Oman; UNESCO Man and the Biosphere Programme; FAO GIAHS","disc":["Rose terraces at 2,000 m","Biosphere reserve listed 2025"],"refs":["Oman Observer (2025). Two Omani reserves listed on UNESCO's biosphere programme.","Wikipedia contributors (2026). Jebel Akhdar (Oman), citing Ministry of Tourism, Gulf News (2011) and UNESCO (2025)."],"conf":"","ev":"","an":"","val":""},{"id":"spec-magan-copper","n":"Ocean Floor, Copper and the Towers of Magan","c":"speculative","s":"Cross-category hypothesis","lat":23.0,"lng":57.5,"p":"Hafit / Umm an-Nar (Early Bronze Age)","dr":"c. 3200–2000 BC (test window)","el":"","desc":"A connection between three records on this map. The Semail ophiolite is a slab of oceanic crust and mantle, more than 10,000 km² of lavas, gabbros and harzburgite, pushed onto Arabia in the Late Cretaceous. Al-Khashbah holds the oldest substantial copper processing in Oman, in a stone tower dated to about 3200 BC, which its excavators link to Uruk texts naming copper from the Arabian Gulf. Bat, 2 km from Al-Khutm, has circular stone towers about 20 m across with no doors, and Salut has a rebuilt Bronze Age tower. The idea: the towers of the 3rd millennium BC stand where they do because the ophiolite nearby carried copper, and the towers were the base of the metal economy that Mesopotamia called Magan.","sig":"If the towers cluster along the copper-bearing edge of the ophiolite, the geology of a Cretaceous ocean floor would explain the map of Oman’s first monumental architecture and its first long-distance trade.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Dates: copper processing at Al-Khashbah Building V c. 3200 cal. BC, mud-brick complex c. 2800 cal. BC; Bat towers and tombs of the 3rd millennium BC; Salut tower of the Bronze Age. Materials: the Semail ophiolite record describes arc lavas, pillow basalts, gabbros and mantle harzburgite, the kind of oceanic crust that elsewhere hosts copper sulphide ores. Position: Al-Khashbah, Bat and Salut all lie in the foothills south and west of the ophiolite belt, within about 100 km of each other. Texts: the Al-Khashbah excavators link the copper to archaic Uruk texts mentioning copper objects from the Gulf.","an":"Cyprus: the Troodos ophiolite, another slab of Cretaceous ocean floor, holds copper sulphide orebodies in its pillow lavas; Bronze Age mining and smelting sites cluster around the ore belt and made Cyprus the copper island of the eastern Mediterranean (Constantinou 1982).","val":"Map all Hafit and Umm an-Nar towers against the ophiolite outcrop and known copper mineralisation; measure distance from each tower to the nearest ore-bearing rock; analyse slag and copper objects from Al-Khashbah, Bat and Salut for lead isotopes and trace elements and compare with ores from the ophiolite; look for Bronze Age mine workings and slag heaps on the ophiolite margin.","disc":["Rival explanation 1: the towers follow water and farmland (the wadis and oasis soils of the foothills), and the ore is a coincidence of the same landscape.","Rival explanation 2: the towers are tombs, storage or territorial markers unconnected to metal, and the copper came from only a few sites such as Al-Khashbah.","Rival explanation 3: the copper of Magan was partly traded in from elsewhere, so ore proximity did not decide where people built."],"refs":["Searle, M. & Cox, J. Tectonic setting, origin, and obduction of the Oman ophiolite. Geological Society of America Bulletin 111(1), 104–122 (1999).","Schmidt, C. & Döpper, S. (2019). The Hafit period at Al-Khashbah, Sultanate of Oman: results of four years of excavations and material studies. Proceedings of the Seminar for Arabian Studies 49, 265–274.","Thornton, C. P., Cable, C. M. & Possehl, G. L. (2016). The Bronze Age Towers at Bat, Sultanate of Oman. University of Pennsylvania Press.","Tagliamonte, E. & Avanzini, A. (2018). New data from the renewed excavation at Salūt: the Iron Age settlement (Qaryat Salūt). Proceedings of the Seminar for Arabian Studies 48, 339–353.","Constantinou, G. (1982). Geological features and ancient exploitation of the cupriferous sulphide orebodies of Cyprus. In Muhly, J. D., Maddin, R. & Karageorghis, V. (eds), Early Metallurgy in Cyprus, 4000–500 BC, 13–24. Pierides Foundation, Nicosia."],"ic":"spark","era":"?","te":"Did the Sea Floor Build the Towers?","ta":"هل بنى قاع البحر الأبراج؟","se":"Oman’s first stone towers rose beside a slab of ancient ocean floor, and the oldest copper smelting in the country sits in one of them. Did the sea floor’s copper decide where Magan built? Nobody has tested this yet.","sa":"ارتفعت أولى أبراج عُمان الحجرية بجوار لوح من قاع محيط قديم، وأقدم صهر للنحاس في البلاد يقع في أحدها. هل قرّر نحاس قاع البحر أين تبني مجان؟ لم يختبر أحد ذلك بعد.","na":"قاع المحيط والنحاس وأبراج مجان","t0":5225,"t1":4025,"spec":{"bas":"link","key":"magan","sty":"ai-magan","spot":{"en":"Born from a coincidence of places on this map. The ophiolite record describes 10,000 km² of ocean crust in the Hajar. The Al-Khashbah record places Oman’s first copper processing in a tower of about 3200 BC and links it to Uruk texts about Gulf copper. Bat and Salut have towers of the same age, all in the foothills of the same mountains.","ar":"وُلدت الفكرة من تطابق أماكن على هذه الخريطة. يصف سجل الأفيوليت 10,000 كيلومتر مربع من قشرة محيطية في الحجر. ويضع سجل الخشبة أول معالجة للنحاس في عُمان في برج يعود إلى نحو 3200 ق.م ويربطها بنصوص أوروك عن نحاس الخليج. ولبات وسلوت أبراج من العمر نفسه، كلها في سفوح الجبال نفسها."},"lk":[["semail-ophiolite","Ocean crust and mantle pushed onto Arabia, 96–94 million years old","قشرة محيطية ووشاح دُفعا فوق الجزيرة العربية، عمرهما 96–94 مليون سنة"],["al-khashbah","Oldest substantial copper processing in Oman, c. 3200 BC, in a stone tower","أقدم معالجة نحاس مهمة في عُمان، نحو 3200 ق.م، في برج حجري"],["bat-al-khutm-al-ayn","Circular towers 20 m across, 3rd millennium BC","أبراج مستديرة قطرها 20 مترًا من الألفية الثالثة ق.م"],["salut-bisya","A Bronze Age tower rebuilt by the Italian mission","برج من العصر البرونزي أعادت البعثة الإيطالية بناءه"]],"pred":{"en":"Towers of the 3rd millennium BC will lie closer to copper-bearing ophiolite rock than chance would predict, and the lead isotopes of copper from Al-Khashbah, Bat and Salut will match ores from the Semail ophiolite rather than any foreign source.","ar":"ستقع أبراج الألفية الثالثة ق.م أقرب إلى صخور الأفيوليت الحاملة للنحاس مما تتوقعه الصدفة، وستطابق نظائر الرصاص في نحاس الخشبة وبات وسلوت خامات أفيوليت سمائل لا أي مصدر أجنبي."},"test":{"en":"Overlay every known Bronze Age tower on the ophiolite and ore maps and test the spacing statistically; run lead-isotope and trace-element analyses on slag and objects from the three sites; survey the ophiolite margin for Bronze Age mines and slag.","ar":"وضع كل الأبراج البرونزية المعروفة فوق خرائط الأفيوليت والخامات واختبار التوزيع إحصائيًا؛ وإجراء تحليل نظائر الرصاص والعناصر النزرة على الخبث والقطع من المواقع الثلاثة؛ ومسح حافة الأفيوليت بحثًا عن مناجم وخبث من العصر البرونزي."},"wrong":{"en":"If the towers are spread evenly across the foothills regardless of ore, or if their copper comes from somewhere other than the ophiolite, the idea fails.","ar":"إذا كانت الأبراج موزّعة بالتساوي على السفوح بصرف النظر عن الخام، أو كان نحاسها من مصدر غير الأفيوليت، تسقط الفكرة."}}},{"id":"spec-khareef-incense","n":"The Monsoon, the Trees and the Ports of Incense","c":"speculative","s":"Cross-category hypothesis","lat":17.16,"lng":54.32,"p":"Late pre-Islamic to medieval","dr":"c. 300 BC – AD 1500 (test window)","el":"","desc":"A connection between four records on this map. The khareef record says the escarpment woodland of figs, olives and frankincense depends on the summer monsoon fog of Dhofar, Arabia’s only monsoon forest. Wadi Dawkah is the living Boswellia sacra woodland whose resin was tapped for the trade of Sumhuram and Zafar. Khor Rori (Sumhuram) was founded at the end of the 1st century BC to control that trade; Shisr was a caravan station on the same network by 300 BC; Al-Baleed (Zafar) was the medieval port. Al Hoota Cave’s stalagmites in the north were used in a 2022 Science study of droughts in late antique Arabia. The idea: the strength of the monsoon over the centuries set the frankincense harvest, and so set when the ports flourished and when they declined.","sig":"If true, a climate record would explain the timing of the incense trade, and the Land of Frankincense would become a case study in how a single weather system shaped an economy that reached Rome and India.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Dependence: the khareef record states that the escarpment woodland, including frankincense, depends on monsoon fog, which arrives from late June to September. Distances: Wadi Dawkah lies about 45 minutes north of Salalah; Khor Rori is east of Salalah; Wadi Darbat is about 50 minutes away; all three sit on one short stretch of the Dhofar coast and mountains. Dates: Shisr in the network by 300 BC; Sumhuram founded end of 1st century BC and occupied into the 5th century AD; Al-Baleed active in the Middle Ages. Method: Al Hoota stalagmites have already yielded a dated drought record for late antique Arabia (Fleitmann et al. 2022), showing the approach works in Oman.","an":"The Akkadian Empire of Mesopotamia collapsed about 4,200 years ago; dust layers in a marine core from the Gulf of Oman record an abrupt drying at exactly that time, linking a climate shift to the end of a trading state (Cullen et al. 2000).","val":"Collect and date stalagmites from caves in the Dhofar escarpment, or lake cores from Wadi Darbat and the khawrs, to build a monsoon-strength record for the last 2,500 years; compare it with the dated occupation phases of Sumhuram, Shisr and Al-Baleed; study charcoal and pollen from the port excavations for changes in Boswellia and the fog woodland.","disc":["Rival explanation 1: the ports rose and fell with politics and shipping routes, such as the fortunes of Hadramawt, Rome and the Indian Ocean trade, not with the harvest.","Rival explanation 2: the lagoon at Khor Rori silted up and closed the harbour, ending Sumhuram regardless of the trees.","Rival explanation 3: demand for incense changed when religions and burial customs changed in the Mediterranean world."],"refs":["Hasan, D. (2023). Everything you need to know about travelling to Salalah during khareef season. The National, 20 July 2023.","UNESCO World Heritage Centre. Land of Frankincense (ref. 1010), inscribed 2000.","Avanzini, A. (ed.) (2008). A Port in Arabia between Rome and the Indian Ocean (3rd C. BC – 5th C. AD): Khor Rori Report 2. L'Erma di Bretschneider.","Zarins, J. (2001). The Land of Incense: archaeological work in the Governorate of Dhofar. Sultan Qaboos University.","Fleitmann, D. et al. (2022). Droughts and societal change: The environmental context for the emergence of Islam in late antique Arabia. Science 376, 1317–1321.","Cullen, H. M., deMenocal, P. B., Hemming, S., Hemming, G., Brown, F. H., Guilderson, T. & Sirocko, F. (2000). Climate change and the collapse of the Akkadian empire: evidence from the deep sea. Geology 28(4), 379–382."],"ic":"spark","era":"?","te":"Did the Fog Decide the Fate of Sumhuram?","ta":"هل قرّر الضباب مصير سمهرم؟","se":"The frankincense trees of Dhofar drink the summer fog, and the ports that sold their resin rose and fell over fifteen centuries. Did a stronger or weaker monsoon set the rhythm of the incense trade? Nobody has tested this yet.","sa":"تشرب أشجار اللبان في ظفار ضباب الصيف، وازدهرت الموانئ التي باعت صمغها وانحدرت على مدى خمسة عشر قرنًا. هل حدّدت قوة الرياح الموسمية أو ضعفها إيقاع تجارة البخور؟ لم يختبر أحد ذلك بعد.","na":"الرياح الموسمية والأشجار وموانئ البخور","t0":2300,"t1":450,"spec":{"bas":"link","key":"khareef","sty":"ai-khareef","spot":{"en":"Born from a coincidence of places on this map. Four records sit within an hour of each other in Dhofar: a monsoon fog woodland, a frankincense park, a port founded to sell the resin, and the lagoons that fill when the khareef comes. A fifth record, far to the north, showed that Omani stalagmites can date ancient droughts.","ar":"وُلدت الفكرة من تطابق أماكن على هذه الخريطة. أربعة سجلات تقع على مسافة ساعة من بعضها في ظفار: غابة ضباب موسمية، ومنتزه للبان، وميناء أُسّس لبيع الصمغ، وبحيرات تمتلئ حين يأتي الخريف. وسجل خامس بعيد في الشمال أثبت أن صواعد الكهوف العُمانية تستطيع تأريخ الجفاف القديم."},"lk":[["khareef-wadi-darbat","The fog-fed woodland of figs, olives and frankincense","غابة الضباب من التين والزيتون واللبان"],["wadi-dawkah","The living Boswellia sacra woodland, still tapped for resin","غابة شجر اللبان الحيّة، ما زالت تُشقّ للصمغ"],["khor-rori-sumhuram","The port founded at the end of the 1st century BC to control the trade","الميناء الذي أُسّس في نهاية القرن الأول ق.م للتحكم في التجارة"],["al-hoota-cave","Stalagmites already used to date droughts in late antique Arabia","صواعد استُخدمت فعلًا لتأريخ الجفاف في الجزيرة العربية القديمة"]],"pred":{"en":"A monsoon record from Dhofar will show stronger fog during the founding and peak of Sumhuram and weaker fog in the centuries when the port faded, and the same pattern will repeat at Al-Baleed.","ar":"سيُظهر سجل موسمي من ظفار ضبابًا أقوى خلال تأسيس سمهرم وذروتها وضبابًا أضعف في القرون التي تلاشى فيها الميناء، وسيتكرر النمط نفسه في البليد."},"test":{"en":"Build a dated monsoon record from Dhofar cave stalagmites or lagoon cores; compare it with the dated phases of the three incense sites; check charcoal and pollen from the ports for changes in frankincense woodland.","ar":"بناء سجل موسمي مؤرَّخ من صواعد كهوف ظفار أو عينات البحيرات؛ ومقارنته بالمراحل المؤرَّخة لمواقع البخور الثلاثة؛ وفحص الفحم وحبوب اللقاح من الموانئ بحثًا عن تغيّرات في غابة اللبان."},"wrong":{"en":"If the monsoon stayed steady while the ports rose and fell, or if Sumhuram declined during a strong-fog century, the idea fails.","ar":"إذا بقيت الرياح الموسمية ثابتة بينما ازدهرت الموانئ وانحدرت، أو إذا انحدرت سمهرم في قرن كان الضباب فيه قويًا، تسقط الفكرة."}}},{"id":"spec-karst-aflaj","n":"Caves Below, Aflaj Above: the Karst Behind the Oases","c":"speculative","s":"Cross-category hypothesis","lat":23.03,"lng":57.45,"p":"Late antique to present","dr":"c. AD 500 – present (test window)","el":"","desc":"A connection between five records on this map. Al Hoota Cave at the foot of Jebel Shams is a karst system about 5 km long with an underground lake 800 m long, formed by water dissolving limestone over about two million years; Bimmah Sinkhole shows the same rock collapsing near the coast, and Majlis al Jinn is a chamber of four million cubic metres in limestone. Falaj Daris at Nizwa heads a system of about 3,000 aflaj dating from around AD 500, of which aini aflaj (28%) carry spring water and daudi aflaj run underground up to 12 km. Jebel Akhdar’s mountain springs feed falaj channels and terraces, and Bahla’s 13 km oasis wall sits at the foot of the same massif. The idea: the great oases of the Dakhiliyah stand where dissolved limestone conduits inside the Hajar discharge their water, and the aflaj were engineered to tap those karst outlets.","sig":"If true, the location of Oman’s historic towns and its 5,000-year irrigation tradition would be explained by a map of cave systems, and protecting the karst would become the same job as protecting the aflaj.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Rock: Al Hoota (5 km of passages, 800 m lake), Bimmah and Majlis al Jinn all formed by dissolution of limestone, showing that the Hajar stores and moves water through conduits. Position: Al Hoota lies about 20 km north-west of Nizwa and Falaj Daris, and about 15 km north of Bahla; Jebel Akhdar’s Saiq plateau at about 2,000 m lies between them and the coast. Water: the falaj record says 28% of aflaj are aini, carrying spring water, sometimes hot, and that mountain springs on Jebel Akhdar feed falaj channels. Dates: the aflaj date from around AD 500 within a 5,000-year irrigation tradition; the caves are about two million years old, so the outlets were there long before the engineers.","an":"The Edwards Aquifer of Texas: a limestone karst whose great springs at San Antonio, New Braunfels and San Marcos fixed the sites of missions and towns, and whose conduit flow explains why the springs respond quickly to rain on the plateau (Sharp & Banner 1997).","val":"Trace dye or tag water chemically in Al Hoota and other Hajar caves and watch for it in the mother wells and springs of Falaj Daris, the Bahla aflaj and the Jebel Akhdar springs; compare the isotopes and temperature of falaj water with cave lake water; map known cave passages against the heads of the aini and daudi aflaj and test whether they coincide more often than chance.","disc":["Rival explanation 1: the aflaj tap shallow alluvial water in the wadi gravels, and the oases follow the big wadis, not the caves.","Rival explanation 2: the oases sit where mountain, plain and trade routes meet, and water was found wherever people decided to settle.","Rival explanation 3: the aini springs rise along faults rather than along dissolved cave conduits."],"refs":["Fleitmann, D. et al. (2022). Droughts and societal change: The environmental context for the emergence of Islam in late antique Arabia. Science 376, 1317–1321.","Rajendran, S. & Nasir, S. (2014). ASTER mapping of limestone formations and study of caves, springs and depressions in parts of Sultanate of Oman. Environmental Earth Sciences 71(1), 133–146.","UNESCO World Heritage Centre. Aflaj Irrigation Systems of Oman (ref. 1207), inscribed 2006.","Al-Ghafri, A. S. (2018). Overview about the aflaj of Oman. Proceedings of the International Symposium of Khettaras and Qanats.","UNESCO World Heritage Centre. Bahla Fort (ref. 433), inscribed 1987; State of Conservation report 2018.","Sharp, J. M. & Banner, J. L. (1997). The Edwards Aquifer: a resource in conflict. GSA Today 7(8), 1–9."],"ic":"spark","era":"?","te":"Do the Oases Sit Where the Caves Drain?","ta":"هل تقع الواحات حيث تصرّف الكهوف ماءها؟","se":"A cave with an 800-metre lake lies a few kilometres from the largest falaj in Oman and the biggest mud fort in the Gulf. Do the oases of the Dakhiliyah sit where the mountain’s hidden rivers come out? Nobody has tested this yet.","sa":"يقع كهف فيه بحيرة طولها 800 متر على بعد كيلومترات قليلة من أكبر فلج في عُمان وأكبر قلعة طينية في الخليج العربي. هل تقع واحات الداخلية حيث تخرج أنهار الجبل الخفية؟ لم يختبر أحد ذلك بعد.","na":"كهوف في الأسفل وأفلاج في الأعلى: الكارست وراء الواحات","t0":1500,"t1":0,"spec":{"bas":"link","key":"karst","sty":"ai-karst","spot":{"en":"Born from a coincidence of places on this map. Al Hoota Cave, Falaj Daris, Bahla Fort and the Saiq plateau all cluster within about 30 km around the southern foot of Jebel Akhdar. The cave record describes water moving through dissolved limestone; the falaj record says more than a quarter of aflaj carry spring water. The two facts seemed to belong together.","ar":"وُلدت الفكرة من تطابق أماكن على هذه الخريطة. يتجمّع كهف الهوتة وفلج دارس وقلعة بهلاء وهضبة سيق كلها في نطاق نحو 30 كيلومترًا حول السفح الجنوبي للجبل الأخضر. يصف سجل الكهف ماءً يتحرك عبر حجر جيري ذائب، ويقول سجل الفلج إن أكثر من ربع الأفلاج يحمل ماء الينابيع. بدا أن الحقيقتين تنتميان إلى بعضهما."},"lk":[["al-hoota-cave","A 5 km karst system with an 800 m underground lake","نظام كارستي طوله 5 كيلومترات فيه بحيرة جوفية طولها 800 متر"],["falaj-daris","Largest of about 3,000 aflaj; 28% carry spring water","أكبر نحو 3,000 فلج؛ 28% منها يحمل ماء الينابيع"],["jebel-akhdar-saiq","Mountain springs feeding falaj channels and terraces at 2,000 m","ينابيع جبلية تغذّي قنوات الأفلاج والمدرّجات على ارتفاع 2,000 متر"],["bahla-fort","An oasis wall of 13 km at the foot of the same massif","سور واحة طوله 13 كيلومترًا عند سفح الكتلة الجبلية نفسها"],["bimmah-sinkhole","The same limestone collapsing where water has eaten it","الحجر الجيري نفسه ينهار حيث أكله الماء"]],"pred":{"en":"Dye or chemical tracers released in the Hajar caves will reappear in the mother wells of aflaj at Nizwa, Bahla or Jebel Akhdar within weeks, and the heads of aini aflaj will cluster along the outlets of mapped cave systems.","ar":"ستظهر الصبغات أو المتتبّعات الكيميائية التي تُطلق في كهوف الحجر مجددًا في الآبار الأم للأفلاج في نزوى أو بهلاء أو الجبل الأخضر خلال أسابيع، وستتجمّع رؤوس الأفلاج العينية عند مخارج أنظمة الكهوف المرسومة."},"test":{"en":"Run dye-tracing from Al Hoota and neighbouring caves to the falaj mother wells; compare water chemistry, isotopes and temperature between cave lakes and aflaj; overlay cave maps on the falaj inventory and test the match statistically.","ar":"إجراء تتبّع بالصبغة من كهف الهوتة والكهوف المجاورة إلى الآبار الأم للأفلاج؛ ومقارنة كيمياء الماء ونظائره وحرارته بين بحيرات الكهوف والأفلاج؛ ووضع خرائط الكهوف فوق جرد الأفلاج واختبار التطابق إحصائيًا."},"wrong":{"en":"If tracers never reach the aflaj, or if falaj water chemically matches wadi gravels rather than cave water, or if the aflaj heads show no relation to the karst, the idea fails.","ar":"إذا لم تصل المتتبّعات إلى الأفلاج قط، أو إذا طابق ماء الفلج كيميائيًا حصى الأودية لا ماء الكهوف، أو إذا لم تُظهر رؤوس الأفلاج أي علاقة بالكارست، تسقط الفكرة."}}},{"id":"spec-om-qurm-larder","n":"The Mangrove Larder of Ras al-Hamra","c":"speculative","s":"Cross-category hypothesis","lat":23.625,"lng":58.49,"p":"Neolithic (Middle Holocene)","dr":"Late 5th – end of 4th millennium BC (test window)","el":"","desc":"A connection between two records on this map. Ras al-Hamra RH-5 is a shell-midden settlement on a large promontory in the Qurm area of Muscat, occupied from the late 5th to the end of the 4th millennium BC; its layers of refuse from fishing, shell collecting, hunting and herding show that exploiting several ecological niches allowed people to live there all year, and it yielded 374 beads of stone and marine shell and a large cemetery. Qurm Nature Reserve, in the same district, is a grey-mangrove (Avicennia marina) creek of about 172 ha whose Ramsar record lists 194 bird species, more than 40 fish species, 27 crustaceans and 48 molluscs, and which serves as a nursery for the capital’s fisheries. The idea: a mangrove creek on this shore was one of the niches that made year-round life at RH-5 possible, a larder that did not run out with the seasons.","sig":"If true, one of the key steps in the neolithisation of Oman, the move to living in one place all year, would rest on a coastal habitat that still survives inside the capital, and protecting Qurm would also protect the setting of Oman’s reference Neolithic village.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Position: RH-5 lies on a promontory in the Qurm area of Muscat, and Qurm Nature Reserve lies in the same district, about 2 km away on this map. Way of life: the RH-5 record describes superimposed refuse from fishing, shell collecting, hunting and herding, with dwellings and household installations, and says that using several ecological niches allowed year-round sedentary occupation. Resources today: the Qurm record lists more than 40 fish species including commercial ones, 27 crustaceans and 48 molluscs, and calls the mangrove a nursery for the capital’s fisheries. Ornament: 374 beads of stone and marine shell show that the sea’s products mattered beyond food.","an":"Coastal Oman: pollen and dated mangrove remains from the Omani coast show that mangroves were more widespread in the middle Holocene than today and later declined, a change the authors linked to the history of coastal settlements (Lézine et al. 2002).","val":"Identify the molluscs, crabs and fish in the RH-5 midden layer by layer and compare them with the 48 molluscs, 27 crustaceans and more than 40 fish species of the Qurm mangrove; core the Qurm creek and date mangrove pollen and wood to the 5th–4th millennium BC; examine charcoal from RH-5 hearths for mangrove wood; use growth lines and oxygen isotopes in the shells to see whether mangrove species were gathered in every season.","disc":["Rival explanation 1: the open sea and rocky shore of the promontory supplied enough food all year, and mangroves played little part.","Rival explanation 2: herding and hunting inland, not the shore, carried the villagers through the lean seasons.","Rival explanation 3: the Qurm mangrove grew up after RH-5 was abandoned, so the village and the creek never met."],"refs":["Marcucci, L. G., Badel, É. & Genchi, F. (2021). Prehistoric fisherfolk of Oman: the Neolithic village of Ras Al-Hamra RH-5. Archaeopress, Oxford.","Pisan, A., Biagi, P. & Gasparotto, G. Stone and shell beads from the shell-midden settlement RH-5, Muscat (Sultanate of Oman). Harappa.com.","Ramsar Sites Information Service. Qurm Nature Reserve, site 2144 (2013).","Kürschner, H. (1986). A Study of the Vegetation of the Qurm Nature Reserve. Arab Gulf Journal of Scientific Research.","Lézine, A.-M., Saliège, J.-F., Robert, C., Wertz, F. & Inizan, M.-L. (2002). Mangroves of Oman during the late Holocene: climatic implications and impact on human settlements. Vegetation History and Archaeobotany 11(3), 221–232."],"ic":"spark","era":"?","te":"Did the Mangroves Keep the Fisherfolk Home All Year?","ta":"هل أبقت أشجار القرم الصيّادين مقيمين طوال العام؟","se":"More than five thousand years ago, fisherfolk lived all year on a headland at Qurm, and today one of the largest mangroves on the east coast of Arabia grows about 2 km away. Did a mangrove creek fill their larder in every season? Nobody has tested this yet.","sa":"قبل أكثر من خمسة آلاف عام عاش صيّادون طوال العام على رأس في القرم، واليوم تنمو على بعد نحو كيلومترين واحدة من أكبر غابات القرم على الساحل الشرقي للجزيرة العربية. هل ملأ خور من أشجار القرم مؤونتهم في كل موسم؟ لم يختبر أحد ذلك بعد.","na":"مؤونة القرم في رأس الحمراء","t0":6325,"t1":5025,"spec":{"bas":"link","key":"omqurm","sty":"ai-omqurm","spot":{"en":"Born from a coincidence of places on this map. The RH-5 record describes a Neolithic village that could stay all year because it used several ecological niches. The Qurm record, about 2 km away, describes a mangrove that is a nursery for fish, crabs and shellfish. On the map the two records almost touch.","ar":"وُلدت الفكرة من تطابق أماكن على هذه الخريطة. يصف سجل RH-5 قرية من العصر الحجري الحديث استطاعت البقاء طوال العام لأنها استغلّت عدة بيئات. ويصف سجل القرم، على بعد نحو كيلومترين، غابة قرم هي حضانة للأسماك والسرطانات والمحار. وعلى الخريطة يكاد السجلان يتلامسان."},"lk":[["ras-al-hamra-rh5","Year-round Neolithic fisher village, late 5th – end of 4th millennium BC","قرية صيّادين من العصر الحجري الحديث مقيمة طوال العام، أواخر الألفية الخامسة حتى نهاية الرابعة ق.م"],["qurm-nature-reserve","Grey-mangrove creek with 40+ fish, 27 crustaceans and 48 molluscs","خور من القرم الرمادي فيه أكثر من 40 نوعًا من الأسماك و27 من القشريات و48 من الرخويات"]],"pred":{"en":"Mangrove and tidal-creek species will appear in every layer of the RH-5 midden and in every season of collection, and cores from the Qurm creek will show mangrove growing there while RH-5 was lived in.","ar":"ستظهر أنواع القرم والخيران المدّية في كل طبقة من أكوام مخلّفات RH-5 وفي كل مواسم الجمع، وستُظهر عينات الحفر من خور القرم أن أشجار القرم كانت تنمو هناك حين كانت RH-5 مأهولة."},"test":{"en":"Sort the midden remains by species and season; core and date the sediments of the Qurm creek; identify the wood burned in the RH-5 hearths.","ar":"فرز بقايا أكوام المخلّفات حسب النوع والموسم؛ وحفر رواسب خور القرم وتأريخها؛ وتحديد نوع الخشب المحروق في مواقد RH-5."},"wrong":{"en":"If the midden holds only open-sea and rocky-shore species, or if the cores show no mangrove at Qurm during the occupation, the idea fails.","ar":"إذا لم تحوِ أكوام المخلّفات إلا أنواع البحر المفتوح والشواطئ الصخرية، أو إذا لم تُظهر العينات أي أشجار قرم في القرم خلال فترة السكن، تسقط الفكرة."}}},{"id":"spec-om-shisr-sinkhole","n":"The Spring That Swallowed a Fort","c":"speculative","s":"Cross-category hypothesis","lat":18.26,"lng":53.65,"p":"Incense trade to late medieval","dr":"c. 300 BC – AD 1500 (test window)","el":"","desc":"A connection between three records on this map. Shisr, north of Thumrait on the edge of the Rub’ al Khali, was a spring and fortified caravan station of the incense trade from by 300 BC to the 16th century AD, and part of its fort collapsed into the sinkhole of its own spring. Bimmah Sinkhole, about 50 by 70 m and 20 m deep, formed when the surface layer collapsed as the limestone beneath it dissolved. Majlis al Jinn is a single chamber of about 4 million m³ in Middle Eocene limestone under a roof only 40 m thick. The idea: the spring at Shisr rose through a dissolving limestone cavity like the one that made Bimmah, and the fort fell when that hidden hollow gave way, perhaps after the water that filled it dropped.","sig":"If true, the ruin of a famous caravan fort would be a geological event, and the same survey methods could warn of hidden voids beneath other spring-side monuments in Oman.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Collapse: the Shisr record says part of the fort collapsed into the sinkhole of its own spring. Process: the Bimmah record describes a sinkhole formed by the collapse of a surface layer as the underlying limestone dissolved, with water at the bottom. Scale: Majlis al Jinn shows that dissolution can leave a chamber 310 m long, 225 m wide and 120 m high under a roof only 40 m thick, so large voids can lie unseen beneath solid-looking ground. Time: Shisr was used from by 300 BC into the 16th century AD, a long span in which its spring could have been drawn on heavily or affected by changes in climate.","an":"The Dead Sea: as the lake level has fallen, swarms of sinkholes have opened along its shores where fresh groundwater dissolves buried salt, showing how a change in water level underground can trigger sudden collapse at the surface (Yechieli et al. 2006).","val":"Run ground-penetrating radar and microgravity surveys beneath and around the Shisr fort to look for cavities; core the sinkhole fill and identify the rock beneath it; date the collapse debris and the fort layers above and below it; study the spring deposits for signs that the water level fell before the collapse.","disc":["Rival explanation 1: the walls were built on soft spring sediments that slumped under their own weight, with no cave involved.","Rival explanation 2: an earthquake shook part of the fort down into the hollow.","Rival explanation 3: people dug the spring deeper to follow falling water and undermined the walls themselves."],"refs":["UNESCO World Heritage Centre. Land of Frankincense (ref. 1010).","Zarins, J. (2001). The Land of Incense: archaeological work in the Governorate of Dhofar. Sultan Qaboos University.","Rajendran, S. & Nasir, S. (2014). ASTER mapping of limestone formations and study of caves, springs and depressions in parts of Sultanate of Oman. Environmental Earth Sciences 71(1), 133–146.","Public Authority for Water Resources, Oman (1985). Report PAWR 85-20.","Yechieli, Y., Abelson, M., Bein, A., Crouvi, O. & Shtivelman, V. (2006). Sinkhole “swarms” along the Dead Sea coast: reflection of disturbance of lake and adjacent groundwater systems. Geological Society of America Bulletin 118(9–10), 1075–1087."],"ic":"spark","era":"?","te":"Did a Hidden Cave Bring Down Shisr?","ta":"هل أسقط كهف خفي قلعة شصر؟","se":"A caravan fort on the edge of the Empty Quarter partly fell into the sinkhole of its own spring. On the coast, Bimmah shows the same kind of hole made by dissolving limestone. Did a hidden cave bring down Shisr? Nobody has tested this yet.","sa":"سقط جزء من قلعة للقوافل على حافة الربع الخالي في بلعة نبعها نفسه. وعلى الساحل تُرينا بلعة بمّه حفرة من النوع نفسه صنعها ذوبان الحجر الجيري. هل أسقط كهف خفي قلعة شصر؟ لم يختبر أحد ذلك بعد.","na":"النبع الذي ابتلع قلعة","t0":2300,"t1":400,"spec":{"bas":"link","key":"omshisr","sty":"ai-omshisr","spot":{"en":"Born from a coincidence of records on this map. The Shisr record mentions, almost in passing, that part of the fort fell into its spring’s sinkhole. The Bimmah and Majlis al Jinn records describe how dissolving limestone leaves hollows that can collapse. One sentence in an archaeology record seemed to need a geology answer.","ar":"وُلدت الفكرة من تطابق سجلات على هذه الخريطة. يذكر سجل شصر، عرضًا تقريبًا، أن جزءًا من القلعة سقط في بلعة نبعها. ويصف سجلا بمّه ومجلس الجن كيف يترك ذوبان الحجر الجيري تجاويف قد تنهار. بدا أن جملة واحدة في سجل أثري تحتاج إلى جواب جيولوجي."},"lk":[["shisr-ubar","Caravan fort whose wall fell into its own spring sinkhole","قلعة قوافل سقط جدارها في بلعة نبعها"],["bimmah-sinkhole","A sinkhole formed as the limestone beneath it dissolved","بلعة تكوّنت حين ذاب الحجر الجيري تحتها"],["majlis-al-jinn","A 4 million m³ chamber under a roof only 40 m thick","قاعة حجمها 4 ملايين متر مكعب تحت سقف سُمكه 40 مترًا فقط"]],"pred":{"en":"Surveys beneath Shisr will find dissolved cavities in soluble rock connected to the spring, and the collapse debris will date to a time when the spring’s water level was falling.","ar":"ستكشف المسوح تحت شصر عن تجاويف ذائبة في صخر قابل للذوبان متصلة بالنبع، وسيعود تاريخ ركام الانهيار إلى زمن كان فيه منسوب ماء النبع ينخفض."},"test":{"en":"Survey for voids with radar and microgravity; core and date the sinkhole fill and the collapse layer; read the spring deposits for a fall in water level.","ar":"المسح بحثًا عن الفراغات بالرادار وقياس الجاذبية الدقيق؛ وحفر ردم البلعة وطبقة الانهيار وتأريخهما؛ وقراءة رواسب النبع بحثًا عن انخفاض في منسوب الماء."},"wrong":{"en":"If the ground under Shisr holds no dissolved cavities, or the collapse layer shows only slumped spring mud, the idea fails.","ar":"إذا لم تحوِ الأرض تحت شصر أي تجاويف ذائبة، أو لم تُظهر طبقة الانهيار سوى طين نبع منزلق، تسقط الفكرة."}}},{"id":"spec-om-wind-sculptor","n":"The Wind Sculptures of Duqm and the Sharqiya Sands","c":"speculative","s":"Geological hypothesis","lat":20.98,"lng":58.25,"p":"Holocene (wind regime since the last ice age)","dr":"c. 11,700 years ago – present (test window)","el":"","desc":"A connection between two records on this map. The Duqm Rock Garden covers about 6 km² of sandstone and limestone in which fragile limestone deposits about 40 million years old are capped by a harder layer, and wind and water erosion over millions of years have sculpted them into symmetrical, statue-like forms. The Sharqiya (Wahiba) Sands is a dune field of about 12,500 km², formed after the last ice age, whose northern dunes rise to 100 m and rest on an older layer of cemented carbonate sand; it is described as the type example of a dune field in the monsoon belt. The idea: the same seasonal wind that builds the Sharqiya dunes is the main sculptor of the Duqm forms, so their shapes and undercut sides record its direction.","sig":"If true, the rocks of Duqm would be a wind gauge set in stone, and read together with the dunes they could show whether the monsoon-belt wind has kept its direction since the last ice age.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Shape: the Duqm record says a harder layer caps fragile limestone and that wind and water erosion sculpted symmetrical forms; soft rock under a hard cap is the classic setting for wind-cut shapes. Wind: the Sharqiya record calls the sand sea the type example of a dune field in the monsoon belt, built after the last ice age. Position: on this map Duqm lies about 300 km south-south-west of the centre of the sands. Memory: the older layer of cemented carbonate sand beneath the Sharqiya dunes may preserve the direction of an earlier wind for comparison.","an":"Yardangs: streamlined ridges carved by wind in deserts around the world line up with the strongest winds, so their orientation can be read as a record of wind direction (Goudie 2007).","val":"Measure the long axes, undercut faces and tapering tails of the Duqm forms from drone images and compare them with dune crest directions in the Sharqiya Sands from satellite images and with modern wind records; map the fractures in the Duqm rock to separate the pull of the wind from the pull of the joints; study cross-bedding in the cemented sand under the Sharqiya dunes for the direction of an older wind.","disc":["Rival explanation 1: the forms follow joints and fractures in the limestone, so their direction is set by the rock, not the wind.","Rival explanation 2: running water and salt weathering did most of the carving, and wind only polished the shapes.","Rival explanation 3: the forms were cut under an older wind regime, and the present wind has barely touched them."],"refs":["Oman Observer (2024). Duqm Rock Garden: A geological marvel, tourist oasis.","Dutton, R. W. (ed.) (1988). The Scientific Results of the Royal Geographical Society’s Oman Wahiba Sands Project 1985–1987. Journal of Oman Studies Special Report 3.","Pease, P. P. et al. (1999). Mineralogical characterization and transport pathways of dune sand using Landsat TM data, Wahiba Sand Sea. Geomorphology.","Goudie, A. S. (2007). Mega-yardangs: a global analysis. Geography Compass 1(1), 65–81."],"ic":"spark","era":"?","te":"Is the Dune Wind the Sculptor of Duqm?","ta":"هل ريح الكثبان هي نحّات الدقم؟","se":"In Duqm, wind and water have carved soft limestone under a hard cap into statues. About 300 kilometres to the north, the Sharqiya Sands are the type dune field of the monsoon belt. Is the dune wind the sculptor of Duqm? Nobody has tested this yet.","sa":"في الدقم نحتت الريح والماء حجرًا جيريًا هشًّا تحت غطاء صلب فصار تماثيل. وعلى بعد نحو 300 كيلومتر شمالًا تقع رمال الشرقية، النموذج المرجعي لحقول الكثبان في حزام الرياح الموسمية. هل ريح الكثبان هي نحّات الدقم؟ لم يختبر أحد ذلك بعد.","na":"منحوتات الريح في الدقم ورمال الشرقية","t0":11700,"t1":0,"spec":{"bas":"link","key":"omwind","sty":"ai-omwind","spot":{"en":"Born from a coincidence of records on this map. The Duqm record says wind helped sculpt the rocks; the Sharqiya record says the sand sea is the type dune field of the monsoon belt. One record shows the wind building, the other shows it carving.","ar":"وُلدت الفكرة من تطابق سجلات على هذه الخريطة. يقول سجل الدقم إن الريح أسهمت في نحت الصخور، ويقول سجل الشرقية إن بحر الرمال هو النموذج المرجعي لحقول الكثبان في حزام الرياح الموسمية. سجل يُرينا الريح وهي تبني، وآخر يُرينا إياها وهي تنحت."},"lk":[["duqm-rock-garden","Soft 40-million-year-old limestone under a hard cap, carved into statues","حجر جيري هشّ عمره 40 مليون سنة تحت غطاء صلب، منحوت كالتماثيل"],["sharqiya-sands","A 12,500 km² sand sea, type dune field of the monsoon belt","بحر رمال مساحته 12,500 كيلومتر مربع، النموذج المرجعي لحقول الكثبان في حزام الرياح الموسمية"]],"pred":{"en":"The long axes and undercut faces of the Duqm forms will line up with the dune-building wind of the Sharqiya Sands, more closely than with the fractures in the rock.","ar":"ستصطف المحاور الطويلة والواجهات المقوّضة لأشكال الدقم مع الريح التي تبني كثبان رمال الشرقية، بدرجة أوثق من اصطفافها مع شقوق الصخر."},"test":{"en":"Map the orientation of the Duqm forms and of the Sharqiya dune crests, compare both with wind records and with the fracture directions, and test the match statistically.","ar":"رسم خريطة لاتجاهات أشكال الدقم ولقمم كثبان الشرقية، ومقارنة كليهما بسجلات الرياح وباتجاهات الشقوق، واختبار التطابق إحصائيًا."},"wrong":{"en":"If the Duqm forms point in random directions, or follow the fractures of the rock rather than the wind, the idea fails.","ar":"إذا كانت أشكال الدقم تتجه اتجاهات عشوائية، أو تتبع شقوق الصخر لا الريح، تسقط الفكرة."}}}],"stops":[]})}catch(e){console.error("D",String(e).slice(0,80))}
